BOOK.add({
  subject: "math",
  id: "math-14",
  title: "समतलीय आकृतियाँ — त्रिभुज, चतुर्भुज तथा वृत्त",
  notes: "\n    <h3>1. त्रिभुज (Triangle) — परिचय और प्रकार</h3>\n    <p>तीन असंरेख बिंदुओं को मिलाने से बनी बंद आकृति त्रिभुज है। इसमें 3 भुजाएँ, 3 कोण और 3 शीर्ष होते हैं। ΔABC में भुजा BC शीर्ष A के सम्मुख है।</p>\n    <table>\n      <tr><th>भुजाओं के आधार पर</th><th>पहचान</th><th>कोणों के आधार पर</th><th>पहचान</th></tr>\n      <tr><td>समबाहु (Equilateral)</td><td>तीनों भुजाएँ बराबर; प्रत्येक कोण 60°</td><td>न्यूनकोण त्रिभुज</td><td>तीनों कोण 90° से कम</td></tr>\n      <tr><td>समद्विबाहु (Isosceles)</td><td>दो भुजाएँ बराबर; उनके सम्मुख कोण (आधार कोण) बराबर</td><td>समकोण त्रिभुज</td><td>एक कोण ठीक 90°</td></tr>\n      <tr><td>विषमबाहु (Scalene)</td><td>तीनों भुजाएँ (और कोण) अलग</td><td>अधिककोण त्रिभुज</td><td>एक कोण 90° से अधिक</td></tr>\n    </table>\n    <ul>\n      <li>किसी त्रिभुज में अधिकतम <b>एक</b> समकोण या <b>एक</b> अधिक कोण हो सकता है; कम से कम दो कोण सदा न्यून होते हैं।</li>\n      <li>समकोण समद्विबाहु त्रिभुज के कोण: 90°, 45°, 45°।</li>\n    </ul>\n\n    <h3>2. त्रिभुज के कोणों के गुण</h3>\n    <ul>\n      <li><b>कोण योग गुण:</b> ∠A + ∠B + ∠C = 180°।</li>\n      <li><b>बाह्य कोण गुण:</b> किसी भुजा को बढ़ाने से बना बाह्य कोण = दोनों अंतः सम्मुख कोणों का योग। अतः बाह्य कोण प्रत्येक अंतः सम्मुख कोण से बड़ा होता है।</li>\n      <li>तीनों बाह्य कोणों (हर शीर्ष पर एक) का योग = 360°।</li>\n      <li>बड़ी भुजा के सम्मुख बड़ा कोण होता है, और बड़े कोण के सम्मुख बड़ी भुजा।</li>\n    </ul>\n    <div class=\"tip\">हल उदाहरण 1: कोणों का अनुपात 2 : 3 : 4 → 180 × 2/9 = 40°, 60°, 80°।<br>हल उदाहरण 2: बाह्य कोण 110°, एक अंतः सम्मुख कोण 45° → दूसरा = 110 − 45 = 65°; तीसरा अंतः कोण = 180 − 110 = 70°।</div>\n\n    <h3>3. त्रिभुज असमिका</h3>\n    <ul>\n      <li>किन्हीं दो भुजाओं का योग तीसरी भुजा से <b>अधिक</b> होता है: a + b &gt; c।</li>\n      <li>किन्हीं दो भुजाओं का अंतर तीसरी भुजा से <b>कम</b> होता है: |a − b| &lt; c।</li>\n      <li>अतः यदि दो भुजाएँ a और b हों तो तीसरी भुजा c: |a − b| &lt; c &lt; a + b।</li>\n      <li>जाँच की ट्रिक: केवल दो छोटी भुजाओं का योग सबसे बड़ी भुजा से बड़ा है या नहीं, यह देखें। (2, 3, 5) से त्रिभुज नहीं बनता क्योंकि 2 + 3 = 5 (बराबर, बड़ा नहीं)।</li>\n    </ul>\n    <div class=\"tip\">हल उदाहरण 3: दो भुजाएँ 5 और 9 → 4 &lt; c &lt; 14 → पूर्णांक मान 5, 6, ..., 13 = 9 मान।</div>\n\n    <h3>4. त्रिभुज की विशेष रेखाएँ और केन्द्र</h3>\n    <table>\n      <tr><th>रेखा</th><th>परिभाषा</th><th>संगमन बिंदु</th><th>विशेष गुण</th></tr>\n      <tr><td>माध्यिका (Median)</td><td>शीर्ष को सम्मुख भुजा के मध्य बिंदु से मिलाने वाली रेखा</td><td>केन्द्रक (Centroid, G)</td><td>G प्रत्येक माध्यिका को शीर्ष से 2 : 1 में बाँटता है; सदा त्रिभुज के अंदर</td></tr>\n      <tr><td>शीर्षलंब (Altitude)</td><td>शीर्ष से सम्मुख भुजा पर डाला गया लंब</td><td>लंबकेन्द्र (Orthocentre, H)</td><td>न्यूनकोण में अंदर, समकोण में समकोण वाले शीर्ष पर, अधिककोण में बाहर</td></tr>\n      <tr><td>लंब समद्विभाजक</td><td>भुजा के मध्य बिंदु से उस पर खींचा गया लंब</td><td>परिकेन्द्र (Circumcentre, O)</td><td>तीनों शीर्षों से समान दूरी (परित्रिज्या R); न्यूनकोण में अंदर, समकोण में कर्ण के मध्य बिंदु पर, अधिककोण में बाहर</td></tr>\n      <tr><td>कोण समद्विभाजक</td><td>शीर्ष के कोण को आधा करने वाली रेखा</td><td>अंतःकेन्द्र (Incentre, I)</td><td>तीनों भुजाओं से समान दूरी (अंतःत्रिज्या r); सदा अंदर</td></tr>\n    </table>\n    <ul>\n      <li>समबाहु त्रिभुज में चारों केन्द्र (G, H, O, I) एक ही बिंदु पर होते हैं।</li>\n      <li>समकोण त्रिभुज में कर्ण पर माध्यिका = कर्ण/2 = परित्रिज्या R।</li>\n      <li>अंतःकेन्द्र I हो तो ∠BIC = 90° + ∠A/2। लंबकेन्द्र H हो तो ∠BHC = 180° − ∠A। परिकेन्द्र O हो (न्यूनकोण त्रिभुज) तो ∠BOC = 2∠A।</li>\n      <li>समबाहु त्रिभुज (भुजा a): ऊँचाई = (√3/2)a, परित्रिज्या = a/√3, अंतःत्रिज्या = a/(2√3)।</li>\n      <li><b>मध्य बिंदु प्रमेय:</b> दो भुजाओं के मध्य बिंदुओं को मिलाने वाला रेखाखंड तीसरी भुजा के समांतर और उसका आधा होता है।</li>\n    </ul>\n\n    <h3>5. पाइथागोरस प्रमेय</h3>\n    <p>समकोण त्रिभुज में <b>(कर्ण)² = (आधार)² + (लंब)²</b>। कर्ण सबसे बड़ी भुजा है और समकोण के सम्मुख होती है।</p>\n    <p><b>विलोम:</b> यदि c² = a² + b² (c सबसे बड़ी भुजा) तो त्रिभुज समकोण है। यदि c² &lt; a² + b² तो न्यूनकोण, और c² &gt; a² + b² तो अधिककोण।</p>\n    <table>\n      <tr><th>मूल पाइथागोरियन त्रिक</th><th>जाँच</th></tr>\n      <tr><td>3, 4, 5</td><td>9 + 16 = 25</td></tr>\n      <tr><td>5, 12, 13</td><td>25 + 144 = 169</td></tr>\n      <tr><td>8, 15, 17</td><td>64 + 225 = 289</td></tr>\n      <tr><td>7, 24, 25</td><td>49 + 576 = 625</td></tr>\n      <tr><td>20, 21, 29</td><td>400 + 441 = 841</td></tr>\n      <tr><td>9, 40, 41</td><td>81 + 1600 = 1681</td></tr>\n      <tr><td>12, 35, 37</td><td>144 + 1225 = 1369</td></tr>\n      <tr><td>11, 60, 61</td><td>121 + 3600 = 3721</td></tr>\n    </table>\n    <p>इनके गुणज भी त्रिक होते हैं: 6-8-10, 9-12-15, 10-24-26, 15-20-25, 16-30-34।</p>\n    <div class=\"tip\">हल उदाहरण 4: 13 मी लंबी सीढ़ी का पाद दीवार से 5 मी दूर है → ऊँचाई = √(169 − 25) = √144 = 12 मी।<br>हल उदाहरण 5: आयत 24 × 7 का विकर्ण = √(576 + 49) = √625 = 25।</div>\n\n    <h3>6. चतुर्भुज (Quadrilateral)</h3>\n    <p>चार भुजाओं वाली बंद आकृति; अंतः कोणों का योग = <b>360°</b> (एक विकर्ण इसे दो त्रिभुजों में बाँटता है)। बाह्य कोणों का योग भी 360°।</p>\n    <table>\n      <tr><th>चतुर्भुज</th><th>भुजाएँ/कोण</th><th>विकर्णों के गुण</th></tr>\n      <tr><td>समांतर चतुर्भुज</td><td>सम्मुख भुजाएँ समांतर व बराबर; सम्मुख कोण बराबर; आसन्न कोण संपूरक</td><td>परस्पर समद्विभाजित करते हैं</td></tr>\n      <tr><td>आयत</td><td>सम्मुख भुजाएँ बराबर; प्रत्येक कोण 90°</td><td>बराबर और परस्पर समद्विभाजित</td></tr>\n      <tr><td>समचतुर्भुज (Rhombus)</td><td>चारों भुजाएँ बराबर; सम्मुख कोण बराबर</td><td>परस्पर लंब समद्विभाजक; शीर्ष कोणों को समद्विभाजित करते हैं; सामान्यतः बराबर नहीं</td></tr>\n      <tr><td>वर्ग</td><td>चारों भुजाएँ बराबर, प्रत्येक कोण 90°</td><td>बराबर, परस्पर लंब समद्विभाजक; विकर्ण = भुजा × √2; भुजा से 45° बनाते हैं</td></tr>\n      <tr><td>समलंब (Trapezium)</td><td>केवल एक युग्म सम्मुख भुजाएँ समांतर</td><td>सामान्य गुण नहीं; समद्विबाहु समलंब में विकर्ण बराबर</td></tr>\n      <tr><td>पतंग (Kite)</td><td>आसन्न भुजाओं के दो युग्म बराबर</td><td>परस्पर लंब; मुख्य विकर्ण दूसरे को समद्विभाजित करता है; एक युग्म सम्मुख कोण बराबर</td></tr>\n    </table>\n    <ul>\n      <li>हर वर्ग एक आयत भी है और समचतुर्भुज भी; हर आयत व समचतुर्भुज समांतर चतुर्भुज है। पर हर आयत वर्ग नहीं।</li>\n      <li>समचतुर्भुज में: भुजा² = (d<sub>1</sub>/2)² + (d<sub>2</sub>/2)²। विकर्ण 16 व 12 → भुजा = √(64 + 36) = 10।</li>\n      <li>किसी भी चतुर्भुज की भुजाओं के मध्य बिंदु मिलाने पर <b>समांतर चतुर्भुज</b> बनता है; आयत से समचतुर्भुज, समचतुर्भुज से आयत, वर्ग से वर्ग बनता है।</li>\n      <li>समांतर चतुर्भुज में आसन्न कोणों के समद्विभाजक परस्पर 90° पर मिलते हैं।</li>\n    </ul>\n    <div class=\"tip\">हल उदाहरण 6: चतुर्भुज के कोण 1 : 2 : 3 : 4 → 360/10 = 36 → 36°, 72°, 108°, 144°।</div>\n\n    <h3>7. बहुभुज (Polygon)</h3>\n    <ul>\n      <li>n भुजाओं वाले बहुभुज के अंतः कोणों का योग = <b>(n − 2) × 180°</b>।</li>\n      <li>किसी भी बहुभुज के बाह्य कोणों का योग = <b>360°</b>।</li>\n      <li>सम बहुभुज का प्रत्येक बाह्य कोण = <b>360°/n</b>; प्रत्येक अंतः कोण = 180° − 360°/n = (n − 2) × 180°/n।</li>\n      <li>भुजाओं की संख्या n = 360 ÷ (एक बाह्य कोण)।</li>\n      <li>विकर्णों की संख्या = <b>n(n − 3)/2</b>। (पंचभुज में 5 विकर्ण = भुजाओं की संख्या।)</li>\n      <li>सम बहुभुज का बाह्य कोण 360 का भाजक होना चाहिए, अतः 50° या 70° बाह्य कोण वाला सम बहुभुज संभव नहीं।</li>\n    </ul>\n    <table>\n      <tr><th>भुजाएँ n</th><th>नाम</th><th>अंतः कोण योग</th><th>सम: प्रत्येक अंतः कोण</th><th>बाह्य कोण</th><th>विकर्ण</th></tr>\n      <tr><td>3</td><td>त्रिभुज</td><td>180°</td><td>60°</td><td>120°</td><td>0</td></tr>\n      <tr><td>4</td><td>चतुर्भुज</td><td>360°</td><td>90°</td><td>90°</td><td>2</td></tr>\n      <tr><td>5</td><td>पंचभुज</td><td>540°</td><td>108°</td><td>72°</td><td>5</td></tr>\n      <tr><td>6</td><td>षट्भुज</td><td>720°</td><td>120°</td><td>60°</td><td>9</td></tr>\n      <tr><td>8</td><td>अष्टभुज</td><td>1080°</td><td>135°</td><td>45°</td><td>20</td></tr>\n      <tr><td>9</td><td>नवभुज</td><td>1260°</td><td>140°</td><td>40°</td><td>27</td></tr>\n      <tr><td>10</td><td>दसभुज</td><td>1440°</td><td>144°</td><td>36°</td><td>35</td></tr>\n      <tr><td>12</td><td>द्वादशभुज</td><td>1800°</td><td>150°</td><td>30°</td><td>54</td></tr>\n    </table>\n    <div class=\"tip\">हल उदाहरण 7: सम बहुभुज का अंतः कोण 150° → बाह्य = 30° → n = 360/30 = 12।<br>हल उदाहरण 8: अंतः कोणों का योग 1260° → n − 2 = 7 → n = 9।</div>\n\n    <h3>8. वृत्त (Circle) — भाग</h3>\n    <table>\n      <tr><th>भाग</th><th>अर्थ</th></tr>\n      <tr><td>केन्द्र, त्रिज्या</td><td>केन्द्र से परिधि के किसी बिंदु तक की दूरी त्रिज्या (r)</td></tr>\n      <tr><td>जीवा (Chord)</td><td>परिधि के दो बिंदुओं को मिलाने वाला रेखाखंड</td></tr>\n      <tr><td>व्यास (Diameter)</td><td>केन्द्र से होकर जाने वाली जीवा = 2r; सबसे लंबी जीवा</td></tr>\n      <tr><td>चाप (Arc)</td><td>परिधि का एक भाग; लघु चाप व दीर्घ चाप</td></tr>\n      <tr><td>त्रिज्यखंड (Sector)</td><td>दो त्रिज्याओं और चाप से घिरा भाग</td></tr>\n      <tr><td>वृत्तखंड (Segment)</td><td>जीवा और चाप से घिरा भाग; लघु व दीर्घ वृत्तखंड</td></tr>\n      <tr><td>छेदक रेखा (Secant)</td><td>वृत्त को दो बिंदुओं पर काटने वाली रेखा</td></tr>\n      <tr><td>स्पर्श रेखा (Tangent)</td><td>वृत्त को केवल एक बिंदु पर छूने वाली रेखा</td></tr>\n    </table>\n\n    <h3>9. वृत्त के प्रमुख गुण (प्रमेय)</h3>\n    <ul>\n      <li>केन्द्र से जीवा पर डाला गया लंब जीवा को समद्विभाजित करता है। जीवा की लंबाई = 2√(r² − d²), जहाँ d = केन्द्र से जीवा की दूरी।</li>\n      <li>बराबर जीवाएँ केन्द्र से समान दूरी पर होती हैं और केन्द्र पर बराबर कोण बनाती हैं।</li>\n      <li>त्रिज्या के बराबर जीवा केन्द्र पर 60° का कोण बनाती है (समबाहु त्रिभुज)।</li>\n      <li><b>चाप द्वारा केन्द्र पर बना कोण, परिधि के शेष भाग पर बने कोण का दोगुना होता है।</b></li>\n      <li>एक ही वृत्तखंड में बने कोण बराबर होते हैं।</li>\n      <li><b>अर्धवृत्त में बना कोण 90° होता है।</b> दीर्घ वृत्तखंड में कोण न्यून, लघु वृत्तखंड में कोण अधिक होता है।</li>\n      <li><b>चक्रीय चतुर्भुज</b> (चारों शीर्ष वृत्त पर) के सम्मुख कोणों का योग 180°। उसका बाह्य कोण = अंतः सम्मुख कोण।</li>\n      <li>चक्रीय समांतर चतुर्भुज सदा आयत होता है; समद्विबाहु समलंब चक्रीय होता है।</li>\n      <li>स्पर्श बिंदु पर त्रिज्या और स्पर्श रेखा परस्पर लंब (90°) होती हैं।</li>\n      <li>वृत्त के बाहर के बिंदु से 2, परिधि के बिंदु से 1, और अंदर के बिंदु से 0 स्पर्श रेखाएँ खींची जा सकती हैं।</li>\n      <li>बाह्य बिंदु से खींची गई दोनों स्पर्श रेखाओं की लंबाई बराबर होती है: लंबाई = √(d² − r²)।</li>\n      <li>बाह्य बिंदु P से स्पर्श रेखाएँ PA, PB हों तो ∠APB + ∠AOB = 180°।</li>\n    </ul>\n    <div class=\"tip\">हल उदाहरण 9: त्रिज्या 13 सेमी, जीवा 24 सेमी → केन्द्र से दूरी = √(169 − 144) = 5 सेमी।<br>हल उदाहरण 10: चक्रीय चतुर्भुज ABCD में ∠A = 2∠C → 3∠C = 180 → ∠C = 60°, ∠A = 120°।</div>\n  ",
  extra: "\n    <h3>शॉर्टकट व गहन ट्रिक्स</h3>\n    <h4>1. त्रिक पहचानने और बनाने की ट्रिक</h4>\n    <ul>\n      <li>विषम संख्या n से त्रिक: (n, (n² − 1)/2, (n² + 1)/2)। n = 7 → 7, 24, 25; n = 9 → 9, 40, 41; n = 11 → 11, 60, 61।</li>\n      <li>सम संख्या n से त्रिक: (n, (n/2)² − 1, (n/2)² + 1)। n = 8 → 8, 15, 17; n = 12 → 12, 35, 37; n = 20 → 20, 99, 101।</li>\n      <li>प्रश्न में संख्याएँ बड़ी हों तो पहले HCF से भाग दें: 30, 72, ? → 6 से भाग → 5, 12, 13 → उत्तर 78।</li>\n      <li>कर्ण के वर्ग का इकाई अंक: पूर्ण वर्ग का इकाई अंक 2, 3, 7, 8 कभी नहीं होता — विकल्प हटाने में उपयोगी।</li>\n    </ul>\n    <h4>2. त्रिभुज के केन्द्रों के कोण-सूत्र (कठिन प्रश्नों के लिए)</h4>\n    <ul>\n      <li>अंतःकेन्द्र: ∠BIC = 90° + A/2। (∠A = 50° → 115°)</li>\n      <li>दो बाह्य कोण समद्विभाजकों से बना कोण (बाह्य केन्द्र): 90° − A/2।</li>\n      <li>लंबकेन्द्र: ∠BHC = 180° − A। (∠A = 60° → 120°)</li>\n      <li>परिकेन्द्र: ∠BOC = 2A (न्यूनकोण त्रिभुज)। (∠A = 70° → 140°)</li>\n      <li>एक आंतरिक व एक बाह्य कोण समद्विभाजक का कोण = A/2।</li>\n      <li>केन्द्रक प्रत्येक माध्यिका को 2 : 1 में बाँटता है; ऑयलर रेखा पर O, G, H संरेख होते हैं और HG : GO = 2 : 1।</li>\n    </ul>\n    <h4>3. भुजाओं से त्रिभुज का प्रकार</h4>\n    <ul>\n      <li>सबसे बड़ी भुजा c लें: c² = a² + b² → समकोण; c² &lt; a² + b² → न्यूनकोण; c² &gt; a² + b² → अधिककोण।</li>\n      <li>दो भुजाएँ a, b दी हों तो तीसरी के संभावित पूर्णांक मानों की संख्या = 2 × (छोटी भुजा) − 1। (5 और 9 → 2 × 5 − 1 = 9)</li>\n    </ul>\n    <h4>4. बहुभुज के एक-पंक्ति हल</h4>\n    <ul>\n      <li>अंतः कोण = k × बाह्य कोण → बाह्य = 180/(k + 1) → n = 2(k + 1)। k = 5 → n = 12; k = 3 → n = 8; k = 2 → n = 6।</li>\n      <li>\"अंतः कोणों का योग, बाह्य कोणों के योग का k गुना\" → n = 2k + 2। k = 3 → 8।</li>\n      <li>विकर्ण D दिए हों: n(n − 3) = 2D। D = 20 → 40 = 8 × 5 → n = 8; D = 35 → 70 = 10 × 7 → n = 10।</li>\n      <li>दो सम बहुभुजों की भुजाओं का अनुपात दिया हो तो बाह्य कोणों का अनुपात उसका उल्टा होता है।</li>\n    </ul>\n    <h4>5. वृत्त की त्वरित बातें</h4>\n    <ul>\n      <li>\"व्यास पर बना त्रिभुज\" दिखे तो तुरंत 90° लिखें — शेष दो कोण पूरक होंगे।</li>\n      <li>जीवा, त्रिज्या, दूरी — तीनों से सदा 3-4-5 / 5-12-13 जैसा त्रिक बनता है: जीवा/2, d, r।</li>\n      <li>स्पर्श रेखा, त्रिज्या और केन्द्र से बाह्य बिंदु की दूरी भी समकोण त्रिभुज बनाते हैं (कर्ण = केन्द्र से बिंदु की दूरी)।</li>\n      <li>चक्रीय चतुर्भुज में विकल्पों में जो कोण-युग्म 180° न जोड़े, उसे हटा दें।</li>\n    </ul>\n    <div class=\"tip\">सावधानी: NCERT के अनुसार समलंब वह चतुर्भुज है जिसकी सम्मुख भुजाओं का एक युग्म समांतर हो; परीक्षा में \"केवल एक युग्म समांतर\" वाली आकृति का उत्तर समलंब ही होता है। पतंग के विकर्ण लंब होते हैं पर दोनों एक-दूसरे को समद्विभाजित नहीं करते।</div>\n  ",
  questions: [
    {"q":"किसी त्रिभुज के कोणों का अनुपात 2 : 3 : 4 है। सबसे बड़ा कोण है —","o":["60°","80°","90°","100°"],"a":1,"e":"<b>हल:</b><br>चरण 1: त्रिभुज के तीनों कोणों का योग = 180°; अनुपात 2 : 3 : 4 → कुल 9 भाग।<br>चरण 2: 1 भाग = 180/9 = 20°।<br>चरण 3: कोण = 40°, 60°, 80° → सबसे बड़ा = 4 × 20 = 80°।<br>अतः उत्तर = <b>80°</b>"},
    {"q":"किसी त्रिभुज के कोण x, 2x और 3x हैं। त्रिभुज किस प्रकार का है?","o":["न्यूनकोण","अधिककोण","समकोण","समबाहु"],"a":2,"e":"<b>हल:</b><br>चरण 1: x + 2x + 3x = 180° → 6x = 180 → x = 30°।<br>चरण 2: कोण = 30°, 60°, 90°।<br>चरण 3: एक कोण 90° → समकोण त्रिभुज।<br>अतः उत्तर = <b>समकोण</b><br><b>ध्यान दें:</b> \"समबाहु\" भुजाओं पर आधारित है; कोण असमान हैं, अतः समबाहु नहीं।"},
    {"q":"त्रिभुज का एक बाह्य कोण 110° है और एक अंतः सम्मुख कोण 45° है। दूसरा अंतः सम्मुख कोण है —","o":["70°","55°","135°","65°"],"a":3,"e":"<b>हल:</b><br>चरण 1: बाह्य कोण प्रमेय: बाह्य कोण = दोनों अंतः सम्मुख कोणों का योग।<br>चरण 2: 110 = 45 + x।<br>चरण 3: x = 110 − 45 = 65°।<br>अतः उत्तर = <b>65°</b><br><b>ध्यान दें:</b> 70° = 180 − 110 संलग्न अंतः कोण है, सम्मुख नहीं।"},
    {"q":"त्रिभुज का एक बाह्य कोण 120° है और उसके दोनों अंतः सम्मुख कोणों का अनुपात 1 : 2 है। बड़ा अंतः सम्मुख कोण है —","o":["80°","40°","60°","90°"],"a":0,"e":"<b>हल:</b><br>चरण 1: दोनों अंतः सम्मुख कोणों का योग = बाह्य कोण = 120°।<br>चरण 2: अनुपात 1 : 2 → 1 भाग = 120/3 = 40°।<br>चरण 3: बड़ा = 2 × 40 = 80° (छोटा 40°)।<br>अतः उत्तर = <b>80°</b>"},
    {"q":"किसी त्रिभुज के तीनों बाह्य कोणों (हर शीर्ष पर एक) का योग होता है —","o":["180°","270°","360°","540°"],"a":2,"e":"<b>हल:</b><br>चरण 1: हर शीर्ष पर अंतः + बाह्य = 180° → तीन शीर्षों पर कुल 3 × 180 = 540°।<br>चरण 2: अंतः कोणों का योग = 180°।<br>चरण 3: बाह्य कोणों का योग = 540 − 180 = 360°।<br>अतः उत्तर = <b>360°</b><br><b>शॉर्टकट:</b> किसी भी बहुभुज के बाह्य कोणों का योग सदा 360°।"},
    {"q":"समबाहु त्रिभुज का प्रत्येक बाह्य कोण कितना होता है?","o":["60°","90°","150°","120°"],"a":3,"e":"<b>हल:</b><br>चरण 1: समबाहु त्रिभुज का प्रत्येक अंतः कोण = 180/3 = 60°।<br>चरण 2: बाह्य कोण = 180 − 60 = 120°।<br>अतः उत्तर = <b>120°</b><br><b>शॉर्टकट:</b> 360/3 = 120°।"},
    {"q":"एक समद्विबाहु त्रिभुज का शीर्ष कोण 40° है। प्रत्येक आधार कोण है —","o":["40°","70°","80°","140°"],"a":1,"e":"<b>हल:</b><br>चरण 1: समद्विबाहु त्रिभुज में दोनों आधार कोण बराबर।<br>चरण 2: 2x + 40 = 180 → 2x = 140।<br>चरण 3: x = 70°।<br>अतः उत्तर = <b>70°</b>"},
    {"q":"एक समद्विबाहु त्रिभुज का प्रत्येक आधार कोण 50° है। शीर्ष कोण है —","o":["80°","50°","100°","65°"],"a":0,"e":"<b>हल:</b><br>चरण 1: दोनों आधार कोण = 50° + 50° = 100°।<br>चरण 2: शीर्ष कोण = 180 − 100 = 80°।<br>अतः उत्तर = <b>80°</b>"},
    {"q":"समकोण समद्विबाहु त्रिभुज के दोनों न्यून कोण होते हैं —","o":["30° व 60°","40° व 50°","45° व 45°","35° व 55°"],"a":2,"e":"<b>हल:</b><br>चरण 1: समकोण = 90° → शेष दो कोणों का योग = 90°।<br>चरण 2: समद्विबाहु → दोनों न्यून कोण बराबर → 90/2 = 45° प्रत्येक।<br>अतः उत्तर = <b>45° व 45°</b>"},
    {"q":"एक त्रिभुज में अधिकतम कितने अधिक कोण हो सकते हैं?","o":["0","2","3","1"],"a":3,"e":"<b>हल:</b><br>चरण 1: अधिक कोण 90° से बड़ा होता है।<br>चरण 2: दो अधिक कोणों का योग ही 180° से अधिक हो जाएगा — त्रिभुज में असंभव।<br>चरण 3: अतः अधिकतम 1 अधिक कोण।<br>अतः उत्तर = <b>1</b><br><b>ध्यान दें:</b> न्यून कोण कम से कम 2 होते हैं — ये दोनों बातें अलग हैं।"},
    {"q":"ΔABC में ∠A + ∠B = 110° और ∠B + ∠C = 120° है। ∠B का मान है —","o":["50°","60°","70°","40°"],"a":0,"e":"<b>हल:</b><br>चरण 1: ∠A + ∠B + ∠C = 180° और ∠A + ∠B = 110° → ∠C = 70°।<br>चरण 2: ∠B + ∠C = 120° → ∠B = 120 − 70 = 50°।<br>अतः उत्तर = <b>50°</b><br><b>शॉर्टकट:</b> ∠B = (110 + 120) − 180 = 50°।"},
    {"q":"निम्न में से किन भुजाओं से त्रिभुज बन सकता है?","o":["3, 4, 8","2, 3, 5","1, 2, 4","5, 6, 10"],"a":3,"e":"<b>हल:</b><br>चरण 1: त्रिभुज असमिका: दो छोटी भुजाओं का योग, सबसे बड़ी भुजा से अधिक होना चाहिए।<br>चरण 2: 3 + 4 = 7, 8 से कम ✗; 2 + 3 = 5, 5 के बराबर ✗ (बराबर होने पर सीधी रेखा); 1 + 2 = 3, 4 से कम ✗।<br>चरण 3: 5 + 6 = 11, 10 से अधिक ✓।<br>अतः उत्तर = <b>5, 6, 10</b>"},
    {"q":"त्रिभुज की दो भुजाएँ 4 सेमी और 7 सेमी हैं। तीसरी भुजा निम्न में से क्या नहीं हो सकती?","o":["4 सेमी","8 सेमी","11 सेमी","10 सेमी"],"a":2,"e":"<b>हल:</b><br>चरण 1: तीसरी भुजा c: (7 − 4) < c < (7 + 4) → 3 < c < 11।<br>चरण 2: 4, 8, 10 इस सीमा में हैं।<br>चरण 3: 11 सीमा के बाहर (बराबर) → संभव नहीं।<br>अतः उत्तर = <b>11 सेमी</b>"},
    {"q":"त्रिभुज की दो भुजाएँ 5 सेमी और 9 सेमी हैं। तीसरी भुजा के कितने पूर्णांक मान संभव हैं?","o":["8","9","10","13"],"a":1,"e":"<b>हल:</b><br>चरण 1: 9 − 5 < c < 9 + 5 → 4 < c < 14।<br>चरण 2: पूर्णांक मान: 5, 6, 7, …, 13।<br>चरण 3: गिनती = 13 − 5 + 1 = 9।<br>अतः उत्तर = <b>9</b><br><b>शॉर्टकट:</b> पूर्णांक मानों की संख्या = 2 × (छोटी भुजा) − 1 = 2 × 5 − 1 = 9।<br><b>ध्यान दें:</b> 4 और 14 सम्मिलित नहीं हैं।"},
    {"q":"त्रिभुज की माध्यिकाएँ जिस बिंदु पर मिलती हैं, वह कहलाता है —","o":["केन्द्रक","परिकेन्द्र","अंतःकेन्द्र","लंबकेन्द्र"],"a":0,"e":"<b>हल:</b><br>चरण 1: माध्यिका = शीर्ष को सम्मुख भुजा के मध्य बिंदु से मिलाने वाला रेखाखंड।<br>चरण 2: तीनों माध्यिकाओं का संगमन बिंदु = केन्द्रक (Centroid)।<br>अतः उत्तर = <b>केन्द्रक</b><br><b>शॉर्टकट:</b> मा-के (माध्यिका-केन्द्रक), को-अं (कोण समद्विभाजक-अंतःकेन्द्र), लं-प (लंब समद्विभाजक-परिकेन्द्र), शी-लं (शीर्षलंब-लंबकेन्द्र)।"},
    {"q":"त्रिभुज के कोणों के समद्विभाजक जिस बिंदु पर मिलते हैं, वह कहलाता है —","o":["केन्द्रक","अंतःकेन्द्र","परिकेन्द्र","लंबकेन्द्र"],"a":1,"e":"<b>हल:</b><br>चरण 1: कोण समद्विभाजकों का संगमन बिंदु = अंतःकेन्द्र (Incentre)।<br>चरण 2: यह तीनों भुजाओं से समान दूरी पर होता है, इसलिए अंतःवृत्त का केन्द्र है।<br>अतः उत्तर = <b>अंतःकेन्द्र</b>"},
    {"q":"त्रिभुज की भुजाओं के लंब समद्विभाजक जिस बिंदु पर मिलते हैं, वह कहलाता है —","o":["केन्द्रक","अंतःकेन्द्र","लंबकेन्द्र","परिकेन्द्र"],"a":3,"e":"<b>हल:</b><br>चरण 1: भुजाओं के लंब समद्विभाजकों का संगमन बिंदु = परिकेन्द्र (Circumcentre)।<br>चरण 2: यह तीनों शीर्षों से समान दूरी पर होता है → परिवृत्त का केन्द्र।<br>अतः उत्तर = <b>परिकेन्द्र</b>"},
    {"q":"त्रिभुज के शीर्षलंब जिस बिंदु पर मिलते हैं, वह कहलाता है —","o":["केन्द्रक","परिकेन्द्र","लंबकेन्द्र","अंतःकेन्द्र"],"a":2,"e":"<b>हल:</b><br>चरण 1: शीर्षलंब = शीर्ष से सम्मुख भुजा पर डाला गया लंब।<br>चरण 2: तीनों शीर्षलंबों का संगमन बिंदु = लंबकेन्द्र (Orthocentre)।<br>अतः उत्तर = <b>लंबकेन्द्र</b>"},
    {"q":"केन्द्रक प्रत्येक माध्यिका को शीर्ष की ओर से किस अनुपात में बाँटता है?","o":["1 : 1","2 : 1","3 : 1","3 : 2"],"a":1,"e":"<b>हल:</b><br>चरण 1: केन्द्रक हर माध्यिका को 2 : 1 में बाँटता है।<br>चरण 2: बड़ा भाग (2) शीर्ष की ओर, छोटा भाग (1) भुजा की ओर।<br>अतः उत्तर = <b>2 : 1</b>"},
    {"q":"समकोण त्रिभुज का लंबकेन्द्र कहाँ स्थित होता है?","o":["कर्ण के मध्य बिंदु पर","त्रिभुज के बाहर","समकोण वाले शीर्ष पर","केन्द्रक पर"],"a":2,"e":"<b>हल:</b><br>चरण 1: समकोण त्रिभुज में समकोण बनाने वाली दोनों भुजाएँ एक-दूसरे पर लंब हैं → वे स्वयं दो शीर्षलंब हैं।<br>चरण 2: ये दोनों समकोण वाले शीर्ष पर मिलती हैं।<br>अतः उत्तर = <b>समकोण वाले शीर्ष पर</b><br><b>ध्यान दें:</b> कर्ण का मध्य बिंदु परिकेन्द्र है, लंबकेन्द्र नहीं।"},
    {"q":"समकोण त्रिभुज का परिकेन्द्र कहाँ स्थित होता है?","o":["कर्ण के मध्य बिंदु पर","समकोण वाले शीर्ष पर","त्रिभुज के बाहर","अंतःकेन्द्र पर"],"a":0,"e":"<b>हल:</b><br>चरण 1: अर्धवृत्त में बना कोण 90° होता है।<br>चरण 2: अतः कर्ण परिवृत्त का व्यास है।<br>चरण 3: परिकेन्द्र = व्यास का मध्य बिंदु = कर्ण का मध्य बिंदु।<br>अतः उत्तर = <b>कर्ण के मध्य बिंदु पर</b>"},
    {"q":"अधिककोण त्रिभुज का लंबकेन्द्र स्थित होता है —","o":["त्रिभुज के अंदर","किसी भुजा के मध्य बिंदु पर","त्रिभुज के बाहर","किसी शीर्ष पर"],"a":2,"e":"<b>हल:</b><br>चरण 1: अधिककोण त्रिभुज में अधिक कोण वाले शीर्ष की आसन्न भुजाओं पर डाले गए शीर्षलंब त्रिभुज के बाहर पड़ते हैं।<br>चरण 2: उन्हें बढ़ाने पर वे त्रिभुज के बाहर मिलते हैं।<br>अतः उत्तर = <b>त्रिभुज के बाहर</b><br><b>शॉर्टकट:</b> लंबकेन्द्र — न्यूनकोण त्रिभुज में अंदर, समकोण में समकोण वाले शीर्ष पर, अधिककोण में बाहर। (परिकेन्द्र — अंदर / कर्ण के मध्य बिंदु पर / बाहर)"},
    {"q":"किस त्रिभुज में केन्द्रक, परिकेन्द्र, अंतःकेन्द्र और लंबकेन्द्र एक ही बिंदु होते हैं?","o":["समद्विबाहु","समकोण","विषमबाहु","समबाहु"],"a":3,"e":"<b>हल:</b><br>चरण 1: समबाहु त्रिभुज में हर माध्यिका = शीर्षलंब = कोण समद्विभाजक = लंब समद्विभाजक।<br>चरण 2: अतः चारों केन्द्र एक ही बिंदु पर।<br>अतः उत्तर = <b>समबाहु</b>"},
    {"q":"एक समकोण त्रिभुज की समकोण बनाने वाली भुजाएँ 6 सेमी और 8 सेमी हैं। इसकी परित्रिज्या है —","o":["10 सेमी","5 सेमी","4 सेमी","6 सेमी"],"a":1,"e":"<b>हल:</b><br>चरण 1: कर्ण = √(6² + 8²) = √(36 + 64) = √100 = 10 सेमी।<br>चरण 2: समकोण त्रिभुज में परित्रिज्या = कर्ण/2।<br>चरण 3: = 10/2 = 5 सेमी।<br>अतः उत्तर = <b>5 सेमी</b><br><b>ध्यान दें:</b> 10 सेमी कर्ण (परिवृत्त का व्यास) है।"},
    {"q":"एक समकोण त्रिभुज की समकोण बनाने वाली भुजाएँ 5 सेमी और 12 सेमी हैं। कर्ण पर खींची गई माध्यिका की लंबाई है —","o":["13 सेमी","6 सेमी","6.5 सेमी","7.5 सेमी"],"a":2,"e":"<b>हल:</b><br>चरण 1: कर्ण = √(5² + 12²) = √169 = 13 सेमी।<br>चरण 2: कर्ण पर माध्यिका = कर्ण/2 (कर्ण का मध्य बिंदु तीनों शीर्षों से समान दूरी पर)।<br>चरण 3: = 13/2 = 6.5 सेमी।<br>अतः उत्तर = <b>6.5 सेमी</b>"},
    {"q":"ΔABC में ∠A = 50° है। ∠B और ∠C के समद्विभाजक बिंदु I पर मिलते हैं। ∠BIC का मान है —","o":["130°","100°","125°","115°"],"a":3,"e":"<b>हल:</b><br>चरण 1: ∠B + ∠C = 180 − 50 = 130°।<br>चरण 2: ΔBIC में ∠IBC + ∠ICB = 130/2 = 65°।<br>चरण 3: ∠BIC = 180 − 65 = 115°।<br>अतः उत्तर = <b>115°</b><br><b>शॉर्टकट:</b> ∠BIC = 90° + ∠A/2 = 90 + 25 = 115°।<br><b>ध्यान दें:</b> 130° = 180 − 50 लंबकेन्द्र वाला सूत्र है; 100° = 2∠A परिकेन्द्र वाला।"},
    {"q":"ΔABC में ∠A = 60° है और H इसका लंबकेन्द्र है। ∠BHC का मान है —","o":["120°","60°","150°","90°"],"a":0,"e":"<b>हल:</b><br>चरण 1: लंबकेन्द्र H के लिए: ∠BHC = 180° − ∠A।<br>चरण 2: = 180 − 60 = 120°।<br>अतः उत्तर = <b>120°</b><br><b>ध्यान दें:</b> संयोग से यहाँ 2∠A भी 120° है, पर सूत्र अलग हैं — ∠A = 70° पर 110° बनाम 140° आता है।"},
    {"q":"एक न्यूनकोण ΔABC में ∠A = 70° है और O इसका परिकेन्द्र है। ∠BOC का मान है —","o":["70°","110°","140°","35°"],"a":2,"e":"<b>हल:</b><br>चरण 1: परिकेन्द्र O → चाप BC केन्द्र पर जो कोण बनाता है वह परिधि पर बने कोण का दोगुना होता है।<br>चरण 2: ∠BOC = 2∠A = 2 × 70 = 140°।<br>अतः उत्तर = <b>140°</b><br><b>ध्यान दें:</b> 110° = 180 − 70 लंबकेन्द्र का सूत्र है।"},
    {"q":"ΔABC में भुजा AB और AC के मध्य बिंदु क्रमशः D और E हैं। यदि BC = 10 सेमी हो तो DE की लंबाई है —","o":["10 सेमी","20 सेमी","4 सेमी","5 सेमी"],"a":3,"e":"<b>हल:</b><br>चरण 1: मध्य बिंदु प्रमेय: दो भुजाओं के मध्य बिंदुओं को मिलाने वाली रेखा तीसरी भुजा के समांतर और उसकी आधी होती है।<br>चरण 2: DE = BC/2 = 10/2 = 5 सेमी।<br>अतः उत्तर = <b>5 सेमी</b>"},
    {"q":"6 सेमी भुजा वाले समबाहु त्रिभुज की ऊँचाई है —","o":["3√3 सेमी","6√3 सेमी","3√2 सेमी","2√3 सेमी"],"a":0,"e":"<b>हल:</b><br>चरण 1: समबाहु त्रिभुज की ऊँचाई = (√3/2) × भुजा।<br>चरण 2: = (√3/2) × 6 = 3√3 सेमी।<br>चरण 3: जाँच (पाइथागोरस): √(6² − 3²) = √27 = 3√3 ✓।<br>अतः उत्तर = <b>3√3 सेमी</b>"},
    {"q":"एक समकोण त्रिभुज की समकोण बनाने वाली भुजाएँ 9 सेमी और 12 सेमी हैं। कर्ण है —","o":["17 सेमी","15 सेमी","21 सेमी","13 सेमी"],"a":1,"e":"<b>हल:</b><br>चरण 1: कर्ण² = 9² + 12² = 81 + 144 = 225।<br>चरण 2: कर्ण = √225 = 15 सेमी।<br>अतः उत्तर = <b>15 सेमी</b><br><b>शॉर्टकट:</b> 9, 12 = 3 × (3, 4) → कर्ण = 3 × 5 = 15।<br><b>ध्यान दें:</b> 21 = 9 + 12 सीधा जोड़ना गलत है।"},
    {"q":"समकोण त्रिभुज का कर्ण 17 सेमी और एक भुजा 8 सेमी है। तीसरी भुजा है —","o":["13 सेमी","12 सेमी","15 सेमी","9 सेमी"],"a":2,"e":"<b>हल:</b><br>चरण 1: भुजा² = कर्ण² − ज्ञात भुजा² = 17² − 8² = 289 − 64 = 225।<br>चरण 2: भुजा = 15 सेमी।<br>अतः उत्तर = <b>15 सेमी</b><br><b>शॉर्टकट:</b> 8-15-17 प्रसिद्ध त्रिक है।"},
    {"q":"निम्न में से कौन-सा पाइथागोरियन त्रिक है?","o":["10, 24, 25","6, 9, 12","7, 23, 25","20, 21, 29"],"a":3,"e":"<b>हल:</b><br>चरण 1: जाँच a² + b² = c²।<br>चरण 2: 10² + 24² = 676 ≠ 625 ✗; 6² + 9² = 117 ≠ 144 ✗; 7² + 23² = 578 ≠ 625 ✗।<br>चरण 3: 20² + 21² = 400 + 441 = 841 = 29² ✓।<br>अतः उत्तर = <b>20, 21, 29</b><br><b>ध्यान दें:</b> 10, 24, 26 त्रिक है (5-12-13 का दोगुना), 25 नहीं।"},
    {"q":"निम्न में से कौन-सा पाइथागोरियन त्रिक नहीं है?","o":["9, 40, 41","8, 14, 17","11, 60, 61","12, 35, 37"],"a":1,"e":"<b>हल:</b><br>चरण 1: 9² + 40² = 81 + 1600 = 1681 = 41² ✓; 11² + 60² = 3721 = 61² ✓; 12² + 35² = 1369 = 37² ✓।<br>चरण 2: 8² + 14² = 64 + 196 = 260, जबकि 17² = 289 ✗।<br>अतः उत्तर = <b>8, 14, 17</b><br><b>ध्यान दें:</b> सही त्रिक 8, 15, 17 है।"},
    {"q":"13 मी लंबी सीढ़ी दीवार से टिकी है और उसका पाद दीवार से 5 मी दूर है। सीढ़ी दीवार पर कितनी ऊँचाई तक पहुँचती है?","o":["12 मी","10 मी","8 मी","11 मी"],"a":0,"e":"<b>हल:</b><br>चरण 1: सीढ़ी = कर्ण = 13 मी, आधार = 5 मी।<br>चरण 2: ऊँचाई = √(13² − 5²) = √(169 − 25) = √144 = 12 मी।<br>अतः उत्तर = <b>12 मी</b><br><b>शॉर्टकट:</b> 5-12-13 त्रिक।"},
    {"q":"24 सेमी लंबे और 7 सेमी चौड़े आयत का विकर्ण है —","o":["24 सेमी","26 सेमी","25 सेमी","31 सेमी"],"a":2,"e":"<b>हल:</b><br>चरण 1: आयत का विकर्ण = √(l² + b²)।<br>चरण 2: = √(24² + 7²) = √(576 + 49) = √625 = 25 सेमी।<br>अतः उत्तर = <b>25 सेमी</b><br><b>शॉर्टकट:</b> 7-24-25 त्रिक।"},
    {"q":"एक व्यक्ति 24 किमी उत्तर और फिर 10 किमी पूर्व चलता है। वह प्रारंभिक बिंदु से कितनी दूर है?","o":["34 किमी","28 किमी","24 किमी","26 किमी"],"a":3,"e":"<b>हल:</b><br>चरण 1: उत्तर और पूर्व परस्पर लंब → समकोण त्रिभुज।<br>चरण 2: दूरी = √(24² + 10²) = √(576 + 100) = √676 = 26 किमी।<br>अतः उत्तर = <b>26 किमी</b><br><b>शॉर्टकट:</b> 10, 24 = 2 × (5, 12) → 2 × 13 = 26।<br><b>ध्यान दें:</b> 34 = 24 + 10 कुल चली गई दूरी है, विस्थापन नहीं।"},
    {"q":"समकोण त्रिभुज की दो भुजाएँ 30 सेमी और 72 सेमी हैं (दोनों समकोण बनाती हैं)। कर्ण है —","o":["78 सेमी","80 सेमी","84 सेमी","75 सेमी"],"a":0,"e":"<b>हल:</b><br>चरण 1: 30 और 72 का सार्व गुणनखंड 6 → 30 = 6 × 5, 72 = 6 × 12।<br>चरण 2: 5-12-13 त्रिक → कर्ण = 6 × 13 = 78 सेमी।<br>चरण 3: जाँच: √(900 + 5184) = √6084 = 78 ✓।<br>अतः उत्तर = <b>78 सेमी</b>"},
    {"q":"भुजाएँ 7 सेमी, 24 सेमी और 25 सेमी वाला त्रिभुज है —","o":["न्यूनकोण","समकोण","अधिककोण","समबाहु"],"a":1,"e":"<b>हल:</b><br>चरण 1: सबसे बड़ी भुजा 25।<br>चरण 2: 7² + 24² = 49 + 576 = 625 = 25²।<br>चरण 3: a² + b² = c² → समकोण त्रिभुज।<br>अतः उत्तर = <b>समकोण</b>"},
    {"q":"भुजाएँ 6 सेमी, 7 सेमी और 10 सेमी वाला त्रिभुज है —","o":["न्यूनकोण","समकोण","अधिककोण","त्रिभुज संभव नहीं"],"a":2,"e":"<b>हल:</b><br>चरण 1: पहले जाँचें त्रिभुज बनता है: 6 + 7 = 13 > 10 ✓।<br>चरण 2: 6² + 7² = 36 + 49 = 85; 10² = 100।<br>चरण 3: 85 < 100 → सबसे बड़ी भुजा के सम्मुख कोण 90° से अधिक → अधिककोण त्रिभुज।<br>अतः उत्तर = <b>अधिककोण</b><br><b>शॉर्टकट:</b> a² + b² > c² → न्यून; = → समकोण; < → अधिक (c = सबसे बड़ी भुजा)।"},
    {"q":"भुजाएँ 5 सेमी, 6 सेमी और 7 सेमी वाला त्रिभुज है —","o":["न्यूनकोण","समकोण","अधिककोण","समद्विबाहु"],"a":0,"e":"<b>हल:</b><br>चरण 1: सबसे बड़ी भुजा 7 → 7² = 49।<br>चरण 2: 5² + 6² = 25 + 36 = 61।<br>चरण 3: 61 > 49 → सबसे बड़ा कोण भी न्यून → न्यूनकोण त्रिभुज।<br>अतः उत्तर = <b>न्यूनकोण</b><br><b>ध्यान दें:</b> भुजाएँ 5, 6, 7 सब अलग हैं, अतः समद्विबाहु नहीं।"},
    {"q":"किसी चतुर्भुज के कोणों का अनुपात 1 : 2 : 3 : 4 है। सबसे बड़ा कोण है —","o":["120°","108°","144°","160°"],"a":2,"e":"<b>हल:</b><br>चरण 1: चतुर्भुज के कोणों का योग = 360°; अनुपात 1 : 2 : 3 : 4 → कुल 10 भाग।<br>चरण 2: 1 भाग = 360/10 = 36°।<br>चरण 3: सबसे बड़ा = 4 × 36 = 144° (कोण 36°, 72°, 108°, 144°)।<br>अतः उत्तर = <b>144°</b>"},
    {"q":"किसी चतुर्भुज के तीन कोण 80°, 95° और 110° हैं। चौथा कोण है —","o":["85°","65°","95°","75°"],"a":3,"e":"<b>हल:</b><br>चरण 1: चतुर्भुज के कोणों का योग = 360°।<br>चरण 2: तीन कोणों का योग = 80 + 95 + 110 = 285°।<br>चरण 3: चौथा = 360 − 285 = 75°।<br>अतः उत्तर = <b>75°</b>"},
    {"q":"समांतर चतुर्भुज का एक कोण 70° है। इसका आसन्न कोण है —","o":["70°","110°","90°","140°"],"a":1,"e":"<b>हल:</b><br>चरण 1: समांतर चतुर्भुज के आसन्न कोण संपूरक (सह-अंतः कोण)।<br>चरण 2: 180 − 70 = 110°।<br>अतः उत्तर = <b>110°</b><br><b>ध्यान दें:</b> 70° सम्मुख कोण है (सम्मुख कोण बराबर होते हैं)।"},
    {"q":"समांतर चतुर्भुज के दो आसन्न कोण (3x + 10)° और (2x + 20)° हैं। छोटा कोण है —","o":["80°","70°","100°","90°"],"a":0,"e":"<b>हल:</b><br>चरण 1: आसन्न कोण संपूरक: (3x + 10) + (2x + 20) = 180।<br>चरण 2: 5x + 30 = 180 → x = 30।<br>चरण 3: कोण: 3 × 30 + 10 = 100°, 2 × 30 + 20 = 80° → छोटा = 80°।<br>अतः उत्तर = <b>80°</b>"},
    {"q":"जिस चतुर्भुज के विकर्ण परस्पर लंब समद्विभाजक हों पर आवश्यक रूप से बराबर न हों, वह है —","o":["आयत","समलंब","समचतुर्भुज","समांतर चतुर्भुज"],"a":2,"e":"<b>हल:</b><br>चरण 1: समचतुर्भुज: विकर्ण एक-दूसरे को समकोण पर समद्विभाजित करते हैं, पर बराबर आवश्यक नहीं।<br>चरण 2: वर्ग में विकर्ण बराबर भी होते हैं; आयत में बराबर पर लंब नहीं; समांतर चतुर्भुज में केवल समद्विभाजित।<br>अतः उत्तर = <b>समचतुर्भुज</b>"},
    {"q":"निम्न में से किस चतुर्भुज के विकर्ण सदा बराबर होते हैं और परस्पर समद्विभाजित करते हैं?","o":["समचतुर्भुज","पतंग","समलंब","आयत"],"a":3,"e":"<b>हल:</b><br>चरण 1: आयत: विकर्ण बराबर और परस्पर समद्विभाजित ✓।<br>चरण 2: समचतुर्भुज: समद्विभाजित पर बराबर नहीं ✗; पतंग, समलंब: समद्विभाजित नहीं ✗।<br>अतः उत्तर = <b>आयत</b><br><b>ध्यान दें:</b> वर्ग में भी यह गुण है, पर वर्ग विकल्प में नहीं है।"},
    {"q":"एक समचतुर्भुज के विकर्ण 16 सेमी और 12 सेमी हैं। इसकी भुजा है —","o":["12 सेमी","10 सेमी","14 सेमी","20 सेमी"],"a":1,"e":"<b>हल:</b><br>चरण 1: विकर्ण परस्पर लंब समद्विभाजक → आधे विकर्ण 8 और 6 सेमी, बीच में समकोण।<br>चरण 2: भुजा = √(8² + 6²) = √(64 + 36) = √100 = 10 सेमी।<br>अतः उत्तर = <b>10 सेमी</b><br><b>ध्यान दें:</b> पूरे विकर्ण (16, 12) सीधे लगाने पर 20 आता है — आधे लेना न भूलें।"},
    {"q":"एक समचतुर्भुज की भुजा 13 सेमी और एक विकर्ण 24 सेमी है। दूसरा विकर्ण है —","o":["12 सेमी","5 सेमी","26 सेमी","10 सेमी"],"a":3,"e":"<b>हल:</b><br>चरण 1: आधा ज्ञात विकर्ण = 24/2 = 12 सेमी।<br>चरण 2: दूसरा आधा विकर्ण = √(13² − 12²) = √(169 − 144) = √25 = 5 सेमी।<br>चरण 3: पूरा दूसरा विकर्ण = 2 × 5 = 10 सेमी।<br>अतः उत्तर = <b>10 सेमी</b><br><b>ध्यान दें:</b> 5 सेमी केवल आधा विकर्ण है।"},
    {"q":"एक समचतुर्भुज की भुजा 8 सेमी और एक कोण 60° है। इसका छोटा विकर्ण है —","o":["8 सेमी","8√3 सेमी","4 सेमी","16 सेमी"],"a":0,"e":"<b>हल:</b><br>चरण 1: समचतुर्भुज की सभी भुजाएँ 8 सेमी।<br>चरण 2: 60° वाले कोण की दोनों भुजाएँ (8, 8) और छोटा विकर्ण त्रिभुज बनाते हैं जिसमें शीर्ष कोण 60° और आधार कोण भी (180 − 60)/2 = 60°।<br>चरण 3: समबाहु त्रिभुज → छोटा विकर्ण = 8 सेमी।<br>अतः उत्तर = <b>8 सेमी</b><br><b>ध्यान दें:</b> 8√3 सेमी बड़ा विकर्ण है।"},
    {"q":"एक वर्ग का विकर्ण 8√2 सेमी है। उसकी भुजा है —","o":["4√2 सेमी","16 सेमी","8 सेमी","8√2 सेमी"],"a":2,"e":"<b>हल:</b><br>चरण 1: वर्ग का विकर्ण = भुजा × √2।<br>चरण 2: भुजा = 8√2 / √2 = 8 सेमी।<br>अतः उत्तर = <b>8 सेमी</b>"},
    {"q":"वर्ग का विकर्ण उसकी भुजा के साथ कितने अंश का कोण बनाता है?","o":["30°","45°","60°","90°"],"a":1,"e":"<b>हल:</b><br>चरण 1: वर्ग का प्रत्येक कोण 90°।<br>चरण 2: विकर्ण इस कोण को समद्विभाजित करता है → 90/2 = 45°।<br>अतः उत्तर = <b>45°</b>"},
    {"q":"जिस चतुर्भुज में सम्मुख भुजाओं का केवल एक युग्म समांतर हो, वह कहलाता है —","o":["समांतर चतुर्भुज","पतंग","समचतुर्भुज","समलंब"],"a":3,"e":"<b>हल:</b><br>चरण 1: केवल एक युग्म सम्मुख भुजाएँ समांतर → समलंब (trapezium)।<br>चरण 2: दोनों युग्म समांतर हों तो समांतर चतुर्भुज।<br>अतः उत्तर = <b>समलंब</b>"},
    {"q":"पतंग (Kite) के विकर्णों के बारे में सत्य कथन है —","o":["वे परस्पर लंब होते हैं","वे सदा बराबर होते हैं","दोनों एक-दूसरे को समद्विभाजित करते हैं","वे समांतर होते हैं"],"a":0,"e":"<b>हल:</b><br>चरण 1: पतंग में दो युग्म आसन्न भुजाएँ बराबर होती हैं।<br>चरण 2: इसके विकर्ण परस्पर लंब होते हैं ✓।<br>चरण 3: केवल मुख्य (सममिति-अक्ष वाला) विकर्ण दूसरे को समद्विभाजित करता है; विकर्ण बराबर नहीं होते।<br>अतः उत्तर = <b>वे परस्पर लंब होते हैं</b>"},
    {"q":"निम्न में से सत्य कथन है —","o":["हर समचतुर्भुज वर्ग है","हर आयत वर्ग है","हर वर्ग समचतुर्भुज है","हर समलंब समांतर चतुर्भुज है"],"a":2,"e":"<b>हल:</b><br>चरण 1: वर्ग: चारों भुजाएँ बराबर → यह समचतुर्भुज की परिभाषा पूरी करता है ✓।<br>चरण 2: हर समचतुर्भुज में कोण 90° नहीं → वर्ग नहीं ✗; हर आयत में भुजाएँ बराबर नहीं ✗; समलंब में केवल एक युग्म समांतर ✗।<br>अतः उत्तर = <b>हर वर्ग समचतुर्भुज है</b>"},
    {"q":"किसी आयत की भुजाओं के मध्य बिंदुओं को क्रम से मिलाने पर बनने वाली आकृति है —","o":["आयत","समचतुर्भुज","समलंब","पतंग"],"a":1,"e":"<b>हल:</b><br>चरण 1: मध्य बिंदु प्रमेय: बनी आकृति की हर भुजा, किसी एक विकर्ण की आधी होती है।<br>चरण 2: आयत के दोनों विकर्ण बराबर → चारों भुजाएँ बराबर।<br>चरण 3: चारों भुजाएँ बराबर → समचतुर्भुज।<br>अतः उत्तर = <b>समचतुर्भुज</b><br><b>शॉर्टकट:</b> समचतुर्भुज के मध्य बिंदु मिलाने पर आयत बनता है (उलटा संबंध)।"},
    {"q":"षट्भुज के अंतः कोणों का योग है —","o":["540°","900°","720°","1080°"],"a":2,"e":"<b>हल:</b><br>चरण 1: अंतः कोणों का योग = (n − 2) × 180°।<br>चरण 2: n = 6 → 4 × 180 = 720°।<br>अतः उत्तर = <b>720°</b>"},
    {"q":"अष्टभुज के अंतः कोणों का योग है —","o":["1080°","720°","900°","1260°"],"a":0,"e":"<b>हल:</b><br>चरण 1: अंतः कोणों का योग = (n − 2) × 180°।<br>चरण 2: n = 8 → 6 × 180 = 1080°।<br>अतः उत्तर = <b>1080°</b>"},
    {"q":"एक सम बहुभुज का प्रत्येक बाह्य कोण 40° है। इसकी भुजाओं की संख्या है —","o":["8","10","12","9"],"a":3,"e":"<b>हल:</b><br>चरण 1: सम बहुभुज में भुजाओं की संख्या n = 360°/बाह्य कोण।<br>चरण 2: n = 360/40 = 9।<br>अतः उत्तर = <b>9</b>"},
    {"q":"एक सम बहुभुज का प्रत्येक अंतः कोण 150° है। इसकी भुजाओं की संख्या है —","o":["10","15","12","18"],"a":2,"e":"<b>हल:</b><br>चरण 1: बाह्य कोण = 180 − 150 = 30°।<br>चरण 2: n = 360/30 = 12।<br>अतः उत्तर = <b>12</b><br><b>ध्यान दें:</b> 360/150 सीधे लेना गलत — पहले बाह्य कोण निकालें।"},
    {"q":"सम पंचभुज का प्रत्येक अंतः कोण है —","o":["72°","108°","120°","100°"],"a":1,"e":"<b>हल:</b><br>चरण 1: बाह्य कोण = 360/5 = 72°।<br>चरण 2: अंतः कोण = 180 − 72 = 108°।<br>अतः उत्तर = <b>108°</b><br><b>ध्यान दें:</b> 72° बाह्य कोण है।"},
    {"q":"सम दसभुज का प्रत्येक अंतः कोण है —","o":["150°","135°","140°","144°"],"a":3,"e":"<b>हल:</b><br>चरण 1: बाह्य कोण = 360/10 = 36°।<br>चरण 2: अंतः कोण = 180 − 36 = 144°।<br>अतः उत्तर = <b>144°</b>"},
    {"q":"सम षट्भुज का प्रत्येक अंतः कोण है —","o":["120°","108°","135°","60°"],"a":0,"e":"<b>हल:</b><br>चरण 1: बाह्य कोण = 360/6 = 60°।<br>चरण 2: अंतः कोण = 180 − 60 = 120°।<br>अतः उत्तर = <b>120°</b>"},
    {"q":"दसभुज में विकर्णों की संख्या है —","o":["45","35","40","70"],"a":1,"e":"<b>हल:</b><br>चरण 1: विकर्णों की संख्या = n(n − 3)/2।<br>चरण 2: n = 10 → 10 × 7/2 = 35।<br>अतः उत्तर = <b>35</b><br><b>ध्यान दें:</b> 45 = ¹⁰C₂ में 10 भुजाएँ भी गिनी जाती हैं: 45 − 10 = 35।"},
    {"q":"किस बहुभुज में 20 विकर्ण होते हैं?","o":["सप्तभुज","नवभुज","अष्टभुज","दसभुज"],"a":2,"e":"<b>हल:</b><br>चरण 1: n(n − 3)/2 = 20 → n(n − 3) = 40।<br>चरण 2: 40 = 8 × 5 (अंतर 3) → n = 8।<br>चरण 3: 8 भुजाएँ = अष्टभुज।<br>अतः उत्तर = <b>अष्टभुज</b>"},
    {"q":"किस बहुभुज में विकर्णों की संख्या उसकी भुजाओं की संख्या के बराबर होती है?","o":["पंचभुज","चतुर्भुज","षट्भुज","सप्तभुज"],"a":0,"e":"<b>हल:</b><br>चरण 1: विकर्ण = n(n − 3)/2, शर्त: n(n − 3)/2 = n।<br>चरण 2: दोनों ओर n से भाग: (n − 3)/2 = 1 → n − 3 = 2।<br>चरण 3: n = 5 → पंचभुज (5 भुजाएँ, 5 विकर्ण)।<br>अतः उत्तर = <b>पंचभुज</b>"},
    {"q":"किसी बहुभुज के अंतः कोणों का योग 1260° है। उसकी भुजाओं की संख्या है —","o":["7","8","10","9"],"a":3,"e":"<b>हल:</b><br>चरण 1: अंतः कोणों का योग = (n − 2) × 180°।<br>चरण 2: (n − 2) × 180 = 1260 → n − 2 = 1260/180 = 7।<br>चरण 3: n = 9।<br>अतः उत्तर = <b>9</b><br><b>ध्यान दें:</b> 7 तो n − 2 है, भुजाएँ नहीं।"},
    {"q":"एक सम बहुभुज का प्रत्येक अंतः कोण उसके बाह्य कोण का 5 गुना है। भुजाओं की संख्या है —","o":["10","12","15","9"],"a":1,"e":"<b>हल:</b><br>चरण 1: सम बहुभुज में अंतः + बाह्य = 180°; अंतः = 5 × बाह्य।<br>चरण 2: बाह्य + 5 बाह्य = 6 बाह्य = 180 → बाह्य = 30°।<br>चरण 3: n = 360/30 = 12।<br>अतः उत्तर = <b>12</b>"},
    {"q":"किसी बहुभुज के अंतः कोणों का योग उसके बाह्य कोणों के योग का तीन गुना है। भुजाओं की संख्या है —","o":["6","7","8","10"],"a":2,"e":"<b>हल:</b><br>चरण 1: बाह्य कोणों का योग सदा 360° → अंतः कोणों का योग = 3 × 360 = 1080°।<br>चरण 2: (n − 2) × 180 = 1080 → n − 2 = 6।<br>चरण 3: n = 8।<br>अतः उत्तर = <b>8</b><br><b>शॉर्टकट:</b> अंतः योग = k × 360 → n = 2k + 2 = 2 × 3 + 2 = 8।"},
    {"q":"निम्न में से कौन-सा किसी सम बहुभुज का बाह्य कोण नहीं हो सकता?","o":["36°","40°","45°","50°"],"a":3,"e":"<b>हल:</b><br>चरण 1: सम बहुभुज में n = 360/बाह्य कोण पूर्णांक होना चाहिए।<br>चरण 2: 360/36 = 10 ✓, 360/40 = 9 ✓, 360/45 = 8 ✓।<br>चरण 3: 360/50 = 7.2 — पूर्णांक नहीं ✗।<br>अतः उत्तर = <b>50°</b>"},
    {"q":"वृत्त की सबसे लंबी जीवा कहलाती है —","o":["त्रिज्या","व्यास","चाप","स्पर्श रेखा"],"a":1,"e":"<b>हल:</b><br>चरण 1: जीवा = वृत्त के दो बिंदुओं को मिलाने वाला रेखाखंड।<br>चरण 2: केन्द्र से होकर जाने वाली जीवा = व्यास = 2r — सबसे लंबी जीवा।<br>अतः उत्तर = <b>व्यास</b><br><b>ध्यान दें:</b> त्रिज्या जीवा नहीं है (उसका एक सिरा केन्द्र पर है)।"},
    {"q":"अर्धवृत्त में बना कोण होता है —","o":["60°","120°","90°","180°"],"a":2,"e":"<b>हल:</b><br>चरण 1: व्यास केन्द्र पर 180° बनाता है।<br>चरण 2: परिधि पर बना कोण = केन्द्र के कोण का आधा = 180/2 = 90°।<br>अतः उत्तर = <b>90°</b>"},
    {"q":"वृत्त का एक चाप केन्द्र पर 120° का कोण बनाता है। वही चाप परिधि के शेष भाग पर कितना कोण बनाएगा?","o":["120°","240°","30°","60°"],"a":3,"e":"<b>हल:</b><br>चरण 1: प्रमेय: चाप द्वारा केन्द्र पर बना कोण = परिधि के शेष भाग पर बने कोण का दोगुना।<br>चरण 2: परिधि पर कोण = 120/2 = 60°।<br>अतः उत्तर = <b>60°</b><br><b>ध्यान दें:</b> 240° प्रतिवर्ती कोण है; उसे दोगुना करना उलटा नियम है।"},
    {"q":"AB किसी वृत्त का व्यास है और C वृत्त पर एक बिंदु है। यदि ∠CAB = 35° तो ∠CBA है —","o":["55°","35°","65°","45°"],"a":0,"e":"<b>हल:</b><br>चरण 1: AB व्यास → ∠ACB = 90° (अर्धवृत्त में कोण)।<br>चरण 2: ΔABC में: ∠CBA = 180 − 90 − 35।<br>चरण 3: = 55°।<br>अतः उत्तर = <b>55°</b><br><b>शॉर्टकट:</b> ∠CAB + ∠CBA = 90° → 90 − 35 = 55°।"},
    {"q":"एक चक्रीय चतुर्भुज का एक कोण 75° है। इसका सम्मुख कोण है —","o":["75°","115°","105°","95°"],"a":2,"e":"<b>हल:</b><br>चरण 1: चक्रीय चतुर्भुज के सम्मुख कोणों का योग = 180°।<br>चरण 2: सम्मुख कोण = 180 − 75 = 105°।<br>अतः उत्तर = <b>105°</b>"},
    {"q":"चक्रीय चतुर्भुज ABCD में ∠A = 2∠C है। ∠A का मान है —","o":["60°","120°","90°","150°"],"a":1,"e":"<b>हल:</b><br>चरण 1: चक्रीय चतुर्भुज: ∠A + ∠C = 180°।<br>चरण 2: 2∠C + ∠C = 180 → 3∠C = 180 → ∠C = 60°।<br>चरण 3: ∠A = 2 × 60 = 120°।<br>अतः उत्तर = <b>120°</b><br><b>ध्यान दें:</b> 60° ∠C है।"},
    {"q":"चक्रीय चतुर्भुज ABCD में ∠A = 85° है। भुजा BC को बिंदु C से आगे E तक बढ़ाया गया है। ∠DCE का मान है —","o":["95°","175°","105°","85°"],"a":3,"e":"<b>हल:</b><br>चरण 1: ∠A + ∠C = 180° (चक्रीय) → ∠BCD = 180 − 85 = 95°।<br>चरण 2: B, C, E एक रेखा पर → ∠DCE = 180 − ∠BCD = 180 − 95 = 85°।<br>अतः उत्तर = <b>85°</b><br><b>शॉर्टकट:</b> चक्रीय चतुर्भुज का बाह्य कोण = अंतः सम्मुख कोण = ∠A।"},
    {"q":"एक चक्रीय समांतर चतुर्भुज सदा होता है —","o":["आयत","समचतुर्भुज","पतंग","समलंब"],"a":0,"e":"<b>हल:</b><br>चरण 1: समांतर चतुर्भुज में सम्मुख कोण बराबर: ∠A = ∠C।<br>चरण 2: चक्रीय होने से ∠A + ∠C = 180° → 2∠A = 180 → ∠A = 90°।<br>चरण 3: सभी कोण 90° → आयत।<br>अतः उत्तर = <b>आयत</b>"},
    {"q":"वृत्त के स्पर्श बिंदु पर स्पर्श रेखा और त्रिज्या के बीच कोण होता है —","o":["45°","60°","90°","180°"],"a":2,"e":"<b>हल:</b><br>चरण 1: प्रमेय: स्पर्श रेखा, स्पर्श बिंदु पर खींची गई त्रिज्या पर लंब होती है।<br>चरण 2: अतः कोण = 90°।<br>अतः उत्तर = <b>90°</b>"},
    {"q":"वृत्त की जीवा और उसके संगत चाप से घिरा भाग कहलाता है —","o":["त्रिज्यखंड","परिधि","चाप","वृत्तखंड"],"a":3,"e":"<b>हल:</b><br>चरण 1: जीवा + उसका चाप → वृत्तखंड (segment)।<br>चरण 2: दो त्रिज्याएँ + चाप → त्रिज्यखंड (sector)।<br>अतः उत्तर = <b>वृत्तखंड</b>"},
    {"q":"दो त्रिज्याओं और उनके बीच के चाप से घिरा भाग कहलाता है —","o":["वृत्तखंड","त्रिज्यखंड","जीवा","व्यास"],"a":1,"e":"<b>हल:</b><br>चरण 1: दो त्रिज्याएँ + उनके बीच का चाप → त्रिज्यखंड (sector)।<br>चरण 2: जीवा + चाप → वृत्तखंड।<br>अतः उत्तर = <b>त्रिज्यखंड</b>"},
    {"q":"वृत्त के बाहर स्थित किसी बिंदु से वृत्त पर कितनी स्पर्श रेखाएँ खींची जा सकती हैं?","o":["2","1","0","अनंत"],"a":0,"e":"<b>हल:</b><br>चरण 1: वृत्त के बाहर का बिंदु → 2 स्पर्श रेखाएँ (दोनों की लंबाई बराबर)।<br>चरण 2: वृत्त पर का बिंदु → 1; वृत्त के अंदर का बिंदु → 0।<br>अतः उत्तर = <b>2</b>"},
    {"q":"वृत्त की त्रिज्या के बराबर लंबाई वाली जीवा केन्द्र पर कितने अंश का कोण बनाती है?","o":["30°","45°","90°","60°"],"a":3,"e":"<b>हल:</b><br>चरण 1: जीवा = r, और दोनों सिरों से केन्द्र तक त्रिज्याएँ = r, r।<br>चरण 2: तीनों भुजाएँ बराबर → समबाहु त्रिभुज।<br>चरण 3: केन्द्र पर कोण = 60°।<br>अतः उत्तर = <b>60°</b>"},
    {"q":"एक ही वृत्तखंड में बने कोण —","o":["संपूरक होते हैं","बराबर होते हैं","पूरक होते हैं","सदा 90° होते हैं"],"a":1,"e":"<b>हल:</b><br>चरण 1: एक ही चाप द्वारा एक ही वृत्तखंड में बने सभी कोण, केन्द्र पर बने कोण के आधे होते हैं।<br>चरण 2: अतः वे सभी आपस में बराबर।<br>अतः उत्तर = <b>बराबर होते हैं</b>"},
    {"q":"लघु वृत्तखंड में बना कोण होता है —","o":["न्यून कोण","समकोण","अधिक कोण","सरल कोण"],"a":2,"e":"<b>हल:</b><br>चरण 1: लघु वृत्तखंड में बना कोण, दीर्घ चाप द्वारा बनाया जाता है।<br>चरण 2: दीर्घ चाप केन्द्र पर 180° से अधिक कोण बनाता है → परिधि पर उसका आधा, 90° से अधिक।<br>अतः उत्तर = <b>अधिक कोण</b><br><b>शॉर्टकट:</b> दीर्घ वृत्तखंड में न्यून, अर्धवृत्त में समकोण, लघु वृत्तखंड में अधिक कोण।"},
    {"q":"केन्द्र से किसी जीवा पर डाला गया लंब —","o":["जीवा को समद्विभाजित करता है","जीवा के समांतर होता है","सदा त्रिज्या के बराबर होता है","जीवा को 1 : 2 में बाँटता है"],"a":0,"e":"<b>हल:</b><br>चरण 1: केन्द्र O से जीवा AB पर लंब OM।<br>चरण 2: ΔOAM और ΔOBM में OA = OB (त्रिज्या), OM उभयनिष्ठ, समकोण → सर्वांगसम (RHS)।<br>चरण 3: अतः AM = MB → जीवा समद्विभाजित।<br>अतः उत्तर = <b>जीवा को समद्विभाजित करता है</b>"},
    {"q":"13 सेमी त्रिज्या वाले वृत्त में 24 सेमी लंबी जीवा की केन्द्र से दूरी है —","o":["12 सेमी","7 सेमी","10 सेमी","5 सेमी"],"a":3,"e":"<b>हल:</b><br>चरण 1: केन्द्र से लंब जीवा को समद्विभाजित करता है → आधी जीवा = 12 सेमी।<br>चरण 2: दूरी = √(r² − 12²) = √(169 − 144) = √25 = 5 सेमी।<br>अतः उत्तर = <b>5 सेमी</b><br><b>शॉर्टकट:</b> 5-12-13 त्रिक।<br><b>ध्यान दें:</b> पूरी जीवा 24 लगाने से गलत उत्तर आता है।"},
    {"q":"10 सेमी त्रिज्या वाले वृत्त में केन्द्र से 6 सेमी दूर स्थित जीवा की लंबाई है —","o":["8 सेमी","12 सेमी","16 सेमी","20 सेमी"],"a":2,"e":"<b>हल:</b><br>चरण 1: आधी जीवा = √(r² − d²) = √(100 − 36) = √64 = 8 सेमी।<br>चरण 2: पूरी जीवा = 2 × 8 = 16 सेमी।<br>अतः उत्तर = <b>16 सेमी</b><br><b>ध्यान दें:</b> 8 सेमी केवल आधी जीवा है।"},
    {"q":"केन्द्र से 13 सेमी दूर स्थित बिंदु से 5 सेमी त्रिज्या वाले वृत्त पर खींची गई स्पर्श रेखा की लंबाई है —","o":["8 सेमी","12 सेमी","18 सेमी","10 सेमी"],"a":1,"e":"<b>हल:</b><br>चरण 1: स्पर्श रेखा ⊥ त्रिज्या → केन्द्र, स्पर्श बिंदु और बाह्य बिंदु से समकोण त्रिभुज (कर्ण = 13)।<br>चरण 2: स्पर्श रेखा = √(13² − 5²) = √(169 − 25) = √144 = 12 सेमी।<br>अतः उत्तर = <b>12 सेमी</b>"},
    {"q":"बाह्य बिंदु P से केन्द्र O वाले वृत्त पर स्पर्श रेखाएँ PA और PB खींची गई हैं। यदि ∠APB = 70° तो ∠AOB है —","o":["70°","140°","110°","90°"],"a":2,"e":"<b>हल:</b><br>चरण 1: OA ⊥ PA और OB ⊥ PB → ∠OAP = ∠OBP = 90°।<br>चरण 2: चतुर्भुज OAPB में कोणों का योग 360°: ∠AOB = 360 − 90 − 90 − 70।<br>चरण 3: = 110°।<br>अतः उत्तर = <b>110°</b><br><b>शॉर्टकट:</b> ∠AOB = 180° − ∠APB।"},
    {"q":"ΔABC में ∠A = ∠B + ∠C तथा ∠B = 2∠C है। ∠C का मान क्या है?","o":["45°","30°","60°","36°"],"a":1,"e":"<b>हल:</b><br>चरण 1: ∠A + ∠B + ∠C = 180° और ∠A = ∠B + ∠C → 2∠A = 180 → ∠A = 90°।<br>चरण 2: ∠B + ∠C = 90 और ∠B = 2∠C → 3∠C = 90।<br>चरण 3: ∠C = 30°।<br>अतः उत्तर = <b>30°</b>"},
    {"q":"एक समद्विबाहु त्रिभुज का शीर्ष कोण, प्रत्येक आधार कोण का दोगुना है। शीर्ष कोण कितना है?","o":["60°","45°","90°","72°"],"a":2,"e":"<b>हल:</b><br>चरण 1: आधार कोण x, x; शीर्ष कोण 2x।<br>चरण 2: x + x + 2x = 180 → 4x = 180 → x = 45°।<br>चरण 3: शीर्ष कोण = 2 × 45 = 90°।<br>अतः उत्तर = <b>90°</b><br><b>ध्यान दें:</b> 45° आधार कोण है।"},
    {"q":"किसी त्रिभुज के कोण समांतर श्रेणी में हैं और सबसे छोटा कोण 40° है। सबसे बड़ा कोण कितना है?","o":["80°","70°","100°","60°"],"a":0,"e":"<b>हल:</b><br>चरण 1: समांतर श्रेणी में कोण: a − d, a, a + d → योग 3a = 180 → a = 60°।<br>चरण 2: a − d = 40 → d = 20।<br>चरण 3: सबसे बड़ा = a + d = 80°।<br>अतः उत्तर = <b>80°</b><br><b>शॉर्टकट:</b> AP में बीच वाला कोण सदा 60°; बड़ा = 2 × 60 − 40 = 80°।"},
    {"q":"ΔABC में ∠B = 50° और ∠C = 70° है। AD, BC पर लंब है और AE, ∠A का समद्विभाजक है। ∠DAE कितना है?","o":["20°","30°","15°","10°"],"a":3,"e":"<b>हल:</b><br>चरण 1: ∠A = 180 − 50 − 70 = 60° → ∠BAE = 60/2 = 30°।<br>चरण 2: ΔABD में ∠ADB = 90° → ∠BAD = 90 − 50 = 40°।<br>चरण 3: ∠DAE = 40 − 30 = 10°।<br>अतः उत्तर = <b>10°</b><br><b>शॉर्टकट:</b> ∠DAE = (∠C − ∠B)/2 = (70 − 50)/2 = 10°।"},
    {"q":"ΔABC में ∠A = 70° है। ∠B और ∠C के बाह्य कोणों के समद्विभाजक बिंदु O पर मिलते हैं। ∠BOC कितना है?","o":["125°","35°","55°","110°"],"a":2,"e":"<b>हल:</b><br>चरण 1: B पर बाह्य कोण = 180 − ∠B, C पर = 180 − ∠C; इनके आधे ΔBOC के दो कोण हैं।<br>चरण 2: ∠OBC + ∠OCB = [360 − (∠B + ∠C)]/2 = [360 − 110]/2 = 125°।<br>चरण 3: ∠BOC = 180 − 125 = 55°।<br>अतः उत्तर = <b>55°</b><br><b>शॉर्टकट:</b> बाह्य समद्विभाजक: 90° − ∠A/2 = 90 − 35 = 55°।<br><b>ध्यान दें:</b> 125° = 90 + ∠A/2 अंतः समद्विभाजकों का सूत्र है।"},
    {"q":"ΔABC में ∠A = 80° है। ∠B का अंतः समद्विभाजक और ∠C का बाह्य समद्विभाजक बिंदु P पर मिलते हैं। ∠BPC कितना है?","o":["40°","80°","50°","140°"],"a":0,"e":"<b>हल:</b><br>चरण 1: C पर बाह्य कोण = ∠A + ∠B → उसका आधा ∠PCE = ∠A/2 + ∠B/2।<br>चरण 2: ΔPBC में P पर कोण: बाह्य कोण ∠PCE = ∠PBC + ∠BPC → ∠A/2 + ∠B/2 = ∠B/2 + ∠BPC।<br>चरण 3: ∠BPC = ∠A/2 = 80/2 = 40°।<br>अतः उत्तर = <b>40°</b>"},
    {"q":"6 मी और 11 मी ऊँचे दो खंभे समतल भूमि पर 12 मी की दूरी पर खड़े हैं। उनके शिखरों के बीच की दूरी कितनी है?","o":["17 मी","12 मी","15 मी","13 मी"],"a":3,"e":"<b>हल:</b><br>चरण 1: शिखरों की ऊँचाई का अंतर = 11 − 6 = 5 मी; क्षैतिज दूरी = 12 मी।<br>चरण 2: दूरी = √(12² + 5²) = √(144 + 25) = √169 = 13 मी।<br>अतः उत्तर = <b>13 मी</b><br><b>ध्यान दें:</b> 17 = 12 + 5 सीधा जोड़ना गलत है।"},
    {"q":"25 मी लंबी सीढ़ी दीवार से टिकी है और उसका पाद दीवार से 7 मी दूर है। यदि सीढ़ी का ऊपरी सिरा 4 मी नीचे खिसक जाए, तो पाद कितना दूर खिसकेगा?","o":["4 मी","8 मी","6 मी","9 मी"],"a":1,"e":"<b>हल:</b><br>चरण 1: प्रारंभिक ऊँचाई = √(25² − 7²) = √(625 − 49) = √576 = 24 मी।<br>चरण 2: 4 मी नीचे खिसकने पर ऊँचाई = 20 मी → नया पाद = √(625 − 400) = √225 = 15 मी।<br>चरण 3: पाद का खिसकना = 15 − 7 = 8 मी।<br>अतः उत्तर = <b>8 मी</b><br><b>ध्यान दें:</b> ऊपर 4 मी खिसकने पर नीचे भी 4 मी नहीं खिसकता।"},
    {"q":"निम्नलिखित कथनों पर विचार कीजिए —<br>1. समकोण त्रिभुज में कर्ण के मध्य बिंदु की तीनों शीर्षों से दूरी बराबर होती है।<br>2. त्रिभुज की किन्हीं दो भुजाओं का अंतर, तीसरी भुजा से अधिक होता है।<br>सही कथन है/हैं —","o":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 न ही 2"],"a":0,"e":"<b>हल:</b><br>चरण 1: कथन 1: कर्ण का मध्य बिंदु = परिकेन्द्र → तीनों शीर्षों से बराबर दूरी → सही।<br>चरण 2: कथन 2: त्रिभुज असमिका से दो भुजाओं का अंतर तीसरी भुजा से सदा कम होता है → गलत।<br>अतः उत्तर = <b>केवल 1</b>"},
    {"q":"12 सेमी भुजा वाले समबाहु त्रिभुज की परित्रिज्या कितनी है?","o":["6√3 सेमी","2√3 सेमी","4√3 सेमी","6 सेमी"],"a":2,"e":"<b>हल:</b><br>चरण 1: समबाहु त्रिभुज में परित्रिज्या R = a/√3।<br>चरण 2: R = 12/√3 = 12√3/3 = 4√3 सेमी।<br>अतः उत्तर = <b>4√3 सेमी</b><br><b>शॉर्टकट:</b> R = ऊँचाई का 2/3 = (2/3) × 6√3 = 4√3।<br><b>ध्यान दें:</b> 2√3 अंतःत्रिज्या है, 6√3 ऊँचाई।"},
    {"q":"एक समकोण त्रिभुज की भुजाएँ 5 सेमी, 12 सेमी और 13 सेमी हैं। इसकी अंतःत्रिज्या कितनी है?","o":["3 सेमी","2.5 सेमी","6.5 सेमी","2 सेमी"],"a":3,"e":"<b>हल:</b><br>चरण 1: समकोण त्रिभुज में अंतःत्रिज्या r = (a + b − c)/2।<br>चरण 2: = (5 + 12 − 13)/2 = 4/2 = 2 सेमी।<br>चरण 3: जाँच: क्षेत्रफल = ½ × 5 × 12 = 30, s = 30/2 = 15 → r = 30/15 = 2 ✓।<br>अतः उत्तर = <b>2 सेमी</b><br><b>ध्यान दें:</b> 6.5 सेमी परित्रिज्या है।"},
    {"q":"ΔABC में DE ∥ BC है, जहाँ D, AB पर और E, AC पर है। यदि AD = 4 सेमी, DB = 6 सेमी और AE = 6 सेमी हो, तो EC कितना है?","o":["4 सेमी","9 सेमी","8 सेमी","10 सेमी"],"a":1,"e":"<b>हल:</b><br>चरण 1: आधारभूत समानुपातिकता (थेल्स) प्रमेय: DE ∥ BC → AD/DB = AE/EC।<br>चरण 2: 4/6 = 6/EC।<br>चरण 3: EC = 6 × 6/4 = 9 सेमी।<br>अतः उत्तर = <b>9 सेमी</b>"},
    {"q":"ΔABC में AB = 6 सेमी, AC = 9 सेमी और BC = 10 सेमी है। ∠A का समद्विभाजक BC को D पर मिलता है। BD कितना है?","o":["5 सेमी","4 सेमी","6 सेमी","3 सेमी"],"a":1,"e":"<b>हल:</b><br>चरण 1: कोण समद्विभाजक प्रमेय: BD/DC = AB/AC = 6/9 = 2/3।<br>चरण 2: BC = 10 को 2 : 3 में बाँटें → 1 भाग = 10/5 = 2।<br>चरण 3: BD = 2 × 2 = 4 सेमी (DC = 6 सेमी)।<br>अतः उत्तर = <b>4 सेमी</b>"},
    {"q":"ΔABC में AB = AC और ∠A = 50° है। शीर्ष B पर बना बाह्य कोण कितना है?","o":["65°","130°","50°","115°"],"a":3,"e":"<b>हल:</b><br>चरण 1: AB = AC → ∠B = ∠C = (180 − 50)/2 = 65°।<br>चरण 2: B पर बाह्य कोण = 180 − 65 = 115°।<br>अतः उत्तर = <b>115°</b><br><b>शॉर्टकट:</b> बाह्य कोण = ∠A + ∠C = 50 + 65 = 115°।<br><b>ध्यान दें:</b> 65° अंतः कोण है।"},
    {"q":"अभिकथन (A): समबाहु त्रिभुज का प्रत्येक कोण 60° होता है।<br>कारण (R): त्रिभुज में बराबर भुजाओं के सम्मुख कोण बराबर होते हैं।","o":["A और R दोनों सही हैं तथा R, A की सही व्याख्या है","A और R दोनों सही हैं परंतु R, A की सही व्याख्या नहीं है","A सही है, R गलत है","A गलत है, R सही है"],"a":0,"e":"<b>हल:</b><br>चरण 1: A: समबाहु त्रिभुज का प्रत्येक कोण 60° — सही।<br>चरण 2: R: बराबर भुजाओं के सम्मुख कोण बराबर — सही प्रमेय।<br>चरण 3: तीनों भुजाएँ बराबर → R से तीनों कोण बराबर → 180/3 = 60° — R ही A का कारण है।<br>अतः उत्तर = <b>A और R दोनों सही हैं तथा R, A की सही व्याख्या है</b>"},
    {"q":"सूची-I (चतुर्भुज) को सूची-II (विकर्णों का गुण) से सुमेलित कीजिए —<br>(A) आयत (B) समचतुर्भुज (C) वर्ग (D) समलंब<br>1. बराबर तथा परस्पर लंब समद्विभाजक 2. बराबर व परस्पर समद्विभाजक, पर सामान्यतः लंब नहीं 3. परस्पर लंब समद्विभाजक, पर सामान्यतः बराबर नहीं 4. सामान्यतः परस्पर समद्विभाजित नहीं करते","o":["A-1, B-3, C-2, D-4","A-2, B-1, C-3, D-4","A-2, B-3, C-1, D-4","A-3, B-2, C-1, D-4"],"a":2,"e":"<b>हल:</b><br>चरण 1: (A) आयत: विकर्ण बराबर व समद्विभाजित, लंब नहीं → 2।<br>चरण 2: (B) समचतुर्भुज: लंब समद्विभाजक, बराबर नहीं → 3।<br>चरण 3: (C) वर्ग: बराबर तथा लंब समद्विभाजक → 1।<br>चरण 4: (D) समलंब: सामान्यतः समद्विभाजित नहीं → 4।<br>अतः उत्तर = <b>A-2, B-3, C-1, D-4</b>"},
    {"q":"आयत ABCD के विकर्ण बिंदु O पर काटते हैं। यदि ∠AOB = 70° हो, तो ∠OAB कितना है?","o":["55°","70°","35°","110°"],"a":0,"e":"<b>हल:</b><br>चरण 1: आयत के विकर्ण बराबर और एक-दूसरे को समद्विभाजित करते हैं → OA = OB।<br>चरण 2: ΔOAB समद्विबाहु → ∠OAB = ∠OBA।<br>चरण 3: ∠OAB = (180 − 70)/2 = 55°।<br>अतः उत्तर = <b>55°</b>"},
    {"q":"समचतुर्भुज ABCD में ∠ABC = 110° है। ∠ACD कितना है?","o":["55°","70°","110°","35°"],"a":3,"e":"<b>हल:</b><br>चरण 1: समचतुर्भुज के आसन्न कोण संपूरक → ∠BCD = 180 − 110 = 70°।<br>चरण 2: समचतुर्भुज का विकर्ण AC, ∠C को समद्विभाजित करता है।<br>चरण 3: ∠ACD = 70/2 = 35°।<br>अतः उत्तर = <b>35°</b><br><b>ध्यान दें:</b> 55° = 110/2 तो ∠ABD है, ∠ACD नहीं।"},
    {"q":"समलंब चतुर्भुज ABCD में AB ∥ DC है। यदि ∠A = 65° हो, तो ∠D कितना है?","o":["65°","25°","115°","130°"],"a":2,"e":"<b>हल:</b><br>चरण 1: AB ∥ DC और AD तिर्यक रेखा।<br>चरण 2: ∠A और ∠D एक ही ओर के अंतः कोण → योग 180°।<br>चरण 3: ∠D = 180 − 65 = 115°।<br>अतः उत्तर = <b>115°</b>"},
    {"q":"चतुर्भुज ABCD में ∠A और ∠B के समद्विभाजक बिंदु P पर मिलते हैं। यदि ∠C + ∠D = 160° हो, तो ∠APB कितना है?","o":["160°","80°","100°","40°"],"a":1,"e":"<b>हल:</b><br>चरण 1: चतुर्भुज: ∠A + ∠B = 360 − 160 = 200°।<br>चरण 2: ΔAPB में ∠PAB + ∠PBA = 200/2 = 100°।<br>चरण 3: ∠APB = 180 − 100 = 80°।<br>अतः उत्तर = <b>80°</b><br><b>शॉर्टकट:</b> ∠APB = (∠C + ∠D)/2 = 160/2 = 80°।"},
    {"q":"एक समांतर चतुर्भुज का परिमाप 60 सेमी है और उसकी आसन्न भुजाएँ 2 : 3 के अनुपात में हैं। बड़ी भुजा कितनी है?","o":["12 सेमी","15 सेमी","24 सेमी","18 सेमी"],"a":3,"e":"<b>हल:</b><br>चरण 1: भुजाएँ 2k और 3k; परिमाप = 2(2k + 3k) = 10k = 60।<br>चरण 2: k = 6।<br>चरण 3: बड़ी भुजा = 3 × 6 = 18 सेमी।<br>अतः उत्तर = <b>18 सेमी</b><br><b>ध्यान दें:</b> परिमाप में हर भुजा दो बार आती है; 60 को 5 भागों में बाँटकर 36 लेना गलत है।"},
    {"q":"5 सेमी त्रिज्या वाले वृत्त के अंतर्गत बने वर्ग की भुजा कितनी है?","o":["5√2 सेमी","10 सेमी","5 सेमी","10√2 सेमी"],"a":0,"e":"<b>हल:</b><br>चरण 1: वृत्त में बने वर्ग का विकर्ण = व्यास = 2 × 5 = 10 सेमी।<br>चरण 2: भुजा = विकर्ण/√2 = 10/√2 = 5√2 सेमी।<br>अतः उत्तर = <b>5√2 सेमी</b>"},
    {"q":"सम षट्भुज और सम अष्टभुज के प्रत्येक अंतः कोण का अनुपात क्या है?","o":["6 : 8","4 : 3","8 : 9","9 : 8"],"a":2,"e":"<b>हल:</b><br>चरण 1: सम षट्भुज: बाह्य = 60° → अंतः = 120°।<br>चरण 2: सम अष्टभुज: बाह्य = 45° → अंतः = 135°।<br>चरण 3: 120 : 135 = (÷15) 8 : 9।<br>अतः उत्तर = <b>8 : 9</b><br><b>ध्यान दें:</b> 9 : 8 उलटा क्रम है।"},
    {"q":"दो सम बहुभुजों की भुजाओं की संख्या का अनुपात 1 : 2 तथा उनके प्रत्येक अंतः कोण का अनुपात 3 : 4 है। उनकी भुजाओं की संख्या क्या है?","o":["4 और 8","5 और 10","6 और 12","3 और 6"],"a":1,"e":"<b>हल:</b><br>चरण 1: भुजाएँ n और 2n; अंतः कोण = 180(n − 2)/n और 180(2n − 2)/(2n) = 180(n − 1)/n।<br>चरण 2: अनुपात = (n − 2)/(n − 1) = 3/4 → 4n − 8 = 3n − 3।<br>चरण 3: n = 5 → भुजाएँ 5 और 10 (जाँच: 108° : 144° = 3 : 4 ✓)।<br>अतः उत्तर = <b>5 और 10</b>"},
    {"q":"5 सेमी त्रिज्या वाले वृत्त में 6 सेमी और 8 सेमी की दो समांतर जीवाएँ केन्द्र के एक ही ओर हैं। जीवाओं के बीच की दूरी कितनी है?","o":["7 सेमी","2 सेमी","1 सेमी","5 सेमी"],"a":2,"e":"<b>हल:</b><br>चरण 1: 6 सेमी जीवा की केन्द्र से दूरी = √(5² − 3²) = √16 = 4 सेमी।<br>चरण 2: 8 सेमी जीवा की दूरी = √(5² − 4²) = √9 = 3 सेमी।<br>चरण 3: एक ही ओर → बीच की दूरी = 4 − 3 = 1 सेमी।<br>अतः उत्तर = <b>1 सेमी</b><br><b>ध्यान दें:</b> 7 सेमी तब आता है जब जीवाएँ केन्द्र के विपरीत ओर हों।"},
    {"q":"केन्द्र O वाले वृत्त पर बिंदु A, B, C स्थित हैं और ∠BAC = 50° है। ∠OBC कितना है?","o":["50°","80°","100°","40°"],"a":3,"e":"<b>हल:</b><br>चरण 1: केन्द्र पर कोण = परिधि पर कोण का दोगुना → ∠BOC = 2 × 50 = 100°।<br>चरण 2: OB = OC (त्रिज्या) → ΔOBC समद्विबाहु।<br>चरण 3: ∠OBC = (180 − 100)/2 = 40°।<br>अतः उत्तर = <b>40°</b><br><b>शॉर्टकट:</b> ∠OBC = 90° − ∠BAC = 90 − 50 = 40°।"},
    {"q":"एक चतुर्भुज ABCD किसी वृत्त के परिगत है (सभी भुजाएँ वृत्त को स्पर्श करती हैं)। AB = 6 सेमी, BC = 7 सेमी, CD = 4 सेमी है। AD कितना है?","o":["5 सेमी","3 सेमी","9 सेमी","4 सेमी"],"a":1,"e":"<b>हल:</b><br>चरण 1: बाह्य बिंदु से खींची स्पर्श रेखाएँ बराबर → परिगत चतुर्भुज में AB + CD = BC + AD।<br>चरण 2: 6 + 4 = 7 + AD।<br>चरण 3: AD = 10 − 7 = 3 सेमी।<br>अतः उत्तर = <b>3 सेमी</b>"},
    {"q":"5 सेमी और 3 सेमी त्रिज्या वाले दो वृत्त एक-दूसरे को बाह्य रूप से स्पर्श करते हैं। उनके केन्द्रों के बीच की दूरी कितनी है?","o":["8 सेमी","2 सेमी","15 सेमी","4 सेमी"],"a":0,"e":"<b>हल:</b><br>चरण 1: बाह्य स्पर्श में स्पर्श बिंदु दोनों केन्द्रों के बीच होता है।<br>चरण 2: केन्द्रों की दूरी = r₁ + r₂ = 5 + 3 = 8 सेमी।<br>अतः उत्तर = <b>8 सेमी</b><br><b>ध्यान दें:</b> 2 सेमी (= 5 − 3) आंतरिक स्पर्श का उत्तर है।"},
    {"q":"दो वृत्त एक-दूसरे को बाह्य रूप से स्पर्श करते हैं। उन पर कुल कितनी उभयनिष्ठ स्पर्श रेखाएँ खींची जा सकती हैं?","o":["2","3","4","1"],"a":1,"e":"<b>हल:</b><br>चरण 1: बाह्य स्पर्श करने वाले वृत्तों पर 2 अनुस्पर्श (direct) रेखाएँ।<br>चरण 2: स्पर्श बिंदु पर 1 उभयनिष्ठ (अनुप्रस्थ) स्पर्श रेखा।<br>चरण 3: कुल = 2 + 1 = 3।<br>अतः उत्तर = <b>3</b><br><b>शॉर्टकट:</b> अलग-अलग (दूर) वृत्त → 4; बाह्य स्पर्श → 3; प्रतिच्छेदी → 2; आंतरिक स्पर्श → 1; एक के अंदर दूसरा → 0।"},
    {"q":"8 सेमी और 3 सेमी त्रिज्या वाले दो वृत्तों के केन्द्रों के बीच की दूरी 13 सेमी है। उनकी अनुस्पर्श (direct common tangent) की लंबाई कितनी है?","o":["13 सेमी","4√3 सेमी","11 सेमी","12 सेमी"],"a":3,"e":"<b>हल:</b><br>चरण 1: अनुस्पर्श की लंबाई = √(d² − (r₁ − r₂)²)।<br>चरण 2: = √(13² − (8 − 3)²) = √(169 − 25) = √144।<br>चरण 3: = 12 सेमी।<br>अतः उत्तर = <b>12 सेमी</b><br><b>ध्यान दें:</b> अनुप्रस्थ स्पर्श रेखा के लिए (r₁ + r₂) लेते हैं: √(169 − 121) = √48 = 4√3 — यह गलत विकल्प इसी से आता है।"},
    {"q":"वृत्त के बिंदु A पर खींची गई स्पर्श रेखा, जीवा AB के साथ 70° का कोण बनाती है। एकांतर वृत्तखंड में जीवा AB द्वारा बनाया गया कोण कितना है?","o":["110°","20°","70°","140°"],"a":2,"e":"<b>हल:</b><br>चरण 1: एकांतर वृत्तखंड प्रमेय: स्पर्श रेखा और जीवा के बीच का कोण = एकांतर वृत्तखंड में जीवा द्वारा बना कोण।<br>चरण 2: अतः कोण = 70°।<br>अतः उत्तर = <b>70°</b><br><b>ध्यान दें:</b> 110° (= 180 − 70) उसी ओर वाले वृत्तखंड का कोण है, एकांतर का नहीं।"},
    {"q":"एक चतुर्भुज के विकर्ण 10 सेमी और 14 सेमी हैं। इसकी भुजाओं के मध्य बिंदुओं को क्रम से मिलाने पर बने चतुर्भुज का परिमाप कितना है?","o":["24 सेमी","48 सेमी","12 सेमी","35 सेमी"],"a":0,"e":"<b>हल:</b><br>चरण 1: मध्य बिंदु प्रमेय: नए चतुर्भुज की हर भुजा, मूल चतुर्भुज के किसी एक विकर्ण की आधी।<br>चरण 2: भुजाएँ = 5, 7, 5, 7।<br>चरण 3: परिमाप = 5 + 7 + 5 + 7 = 24 सेमी।<br>अतः उत्तर = <b>24 सेमी</b><br><b>शॉर्टकट:</b> परिमाप = दोनों विकर्णों का योग = 10 + 14 = 24।"},
    {"q":"एक समकोण त्रिभुज की समकोण बनाने वाली भुजाएँ 6 सेमी और 8 सेमी हैं। समकोण वाले शीर्ष से कर्ण पर डाले गए लंब की लंबाई कितनी है?","o":["5 सेमी","7 सेमी","4 सेमी","4.8 सेमी"],"a":3,"e":"<b>हल:</b><br>चरण 1: कर्ण = √(6² + 8²) = 10 सेमी।<br>चरण 2: क्षेत्रफल दो तरह से: ½ × 6 × 8 = ½ × 10 × लंब।<br>चरण 3: लंब = 48/10 = 4.8 सेमी।<br>अतः उत्तर = <b>4.8 सेमी</b><br><b>शॉर्टकट:</b> लंब = (a × b)/c।<br><b>ध्यान दें:</b> 5 सेमी कर्ण पर माध्यिका है, लंब नहीं।"},
    {"q":"एक सम बहुभुज का प्रत्येक अंतः कोण, प्रत्येक बाह्य कोण से 108° अधिक है। बहुभुज की भुजाओं की संख्या कितनी है?","o":["10","8","12","5"],"a":0,"e":"<b>हल:</b><br>चरण 1: अंतः (I) + बाह्य (E) = 180°; I − E = 108°।<br>चरण 2: घटाने पर: 2E = 180 − 108 = 72 → E = 36°।<br>चरण 3: भुजाएँ = 360/36 = 10।<br>अतः उत्तर = <b>10</b>"},
    {"q":"ΔABC में ∠A = 90° है और AD, BC पर लंब है। यदि BD = 4 सेमी और DC = 9 सेमी हो, तो AD कितना है?","o":["6.5 सेमी","6 सेमी","5 सेमी","36 सेमी"],"a":1,"e":"<b>हल:</b><br>चरण 1: समकोण शीर्ष से कर्ण पर लंब → ΔABD ~ ΔCAD।<br>चरण 2: AD/BD = DC/AD → AD² = BD × DC = 4 × 9 = 36।<br>चरण 3: AD = 6 सेमी।<br>अतः उत्तर = <b>6 सेमी</b><br><b>ध्यान दें:</b> 36 AD² है, AD नहीं।"},
    {"q":"तीन असंरेख बिंदुओं से होकर कितने वृत्त खींचे जा सकते हैं?","o":["अनंत","2","केवल 1","शून्य"],"a":2,"e":"<b>हल:</b><br>चरण 1: तीन असंरेख बिंदु → एक त्रिभुज।<br>चरण 2: इन्हें मिलाने वाली दो जीवाओं के लंब समद्विभाजक ठीक एक बिंदु (परिकेन्द्र) पर मिलते हैं।<br>चरण 3: अतः ठीक एक वृत्त (परिवृत्त)।<br>अतः उत्तर = <b>केवल 1</b><br><b>ध्यान दें:</b> संरेख बिंदुओं से कोई वृत्त नहीं; दो बिंदुओं से अनंत वृत्त।"}
  ]
});
